function ic(n,size=17){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]||ICONS.plane}"/></svg>`;}
const NAV=[['overview','grid','经营总览'],['routes','route','航线网络'],['schedule','clock','航班排班'],['insights','globe','市场洞察'],['fleet','plane','机队管理'],['market','wallet','飞机采购'],['service','star','旅客服务'],['events','globe','世界动态'],['finance','chart','财务中心'],['ranking','award','航司排行榜'],['company','building','公司发展'],['hangar','tool','机库经营']];
let state,view='overview',fleetFilter='全部',marketFilter='全部',makerFilter='全部制造商',purchaseChannel='全部货源',rankFilter='全部',rankQuery='',mapMode='china',lastFocus=null,needsSetup=false,insightBase='',insightCountry='全部国家 / 地区',insightSort='gap',schedulePlane=0;
let dashboardTab='dispatch',networkTab='list',pages={},pageMeta={},setupDraft={name:'云际航空',base:'HGH'},setupFirst=false,setupStage=0,routeStage=0,viewportMode=layoutMode();
let simulationRunning=false,simulationTimer=null,resumeOnNoticeClose=false,resumeSingleAfterChoice=false,retirementResumeSingle=false;
let scheduleMode='route',scheduleFrom='',scheduleTo='',scheduleDirection='out',scheduleDay='all';
let saveError=false,saveIssue='',saveStore;try{saveStore=AIR_SAVE.create(localStorage);}catch{saveStore=AIR_SAVE.create(null);}const loadedSave=saveStore.load();state=loadedSave.state;needsSetup=loadedSave.empty;saveError=!!loadedSave.error;saveIssue=loadedSave.error||'';
function money(n,sign=false){if(!Number.isFinite(n))return '—';let ab=Math.abs(n),pre=n<0?'−':sign&&n>0?'+':'';return pre+(ab>=100?(ab/100).toFixed(2)+' 亿':ab>=1?(ab*100).toFixed(0)+' 万':(ab*100).toFixed(1)+' 万');}
function dateText(d=state.date){return d.replaceAll('-','.');}function pct(v){return (v*100).toFixed(0)+'%';}function button(text,action,icon='',extra='',cls=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${icon?ic(icon,14):''}${text}</button>`;}
function save(){try{saveStore.write(state);saveError=false;return true;}catch(error){saveError=true;saveIssue=error.message;toast('未自动保存：'+error.message+' 可导出当前进度。');return false;}}
function downloadSave(raw,name){const blob=new Blob([raw],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function renderRecovery(){const backups=saveStore.backups();$('#modal-root').innerHTML='';$('#app').innerHTML=`<main class="save-recovery panel padded"><span class="tag amber">原存档已保留 · 自动写入已暂停</span><h1>先找回你的航空公司</h1><p>${esc(saveIssue)}</p><p>不会自动创建新局，也不会用初始进度覆盖旧存档。</p><div class="recovery-actions">${button('导出原始存档','exportOriginal','download')}${button('重新读取','retrySave','arrow')}${button('导入存档文件','selectImport','book')}</div>${backups.map(b=>`<section class="settings-row"><div><h3>${b.label}</h3><p>${esc(b.name)} · 第 ${b.week} 周 · ${dateText(b.date)}</p></div>${button('查看恢复','restoreSave','',`data-backup="${b.id}"`)}</section>`).join('')}</main>`;}
function resetLoadedUI(){retirementResumeSingle=false;resumeSingleAfterChoice=false;resumeOnNoticeClose=false;settlementToken='';settlementItems=[];advisorItems=[];activeAdvice=null;}
function restoreSave(id){const b=saveStore.backups().find(b=>b.id===id);if(!b){toast('未找到可用备份。');return;}showModal('恢复这份经营进度',`<p>${esc(b.name)} · 第 ${b.week} 周 · ${dateText(b.date)}</p><p>来源：${b.label}。恢复后从这一周继续；当前存档会先保留为备份。</p><div class="form-actions">${button('取消','closeModal')}${button('恢复并继续','confirmRestore','arrow',`data-backup="${id}"`,'primary')}</div>`);}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function act(type,a,msg){if(!state){renderRecovery();return false;}try{const newsCount=state.companyNews?.length||0;E.action(state,type,a);const done=activeAdvice&&adviceActionMatches(activeAdvice,type,a);if(done)finishAdvice(activeAdvice.key);const saved=save();closeModal();render();toast(saved?(msg||'操作已完成'):'操作已完成，但自动保存失败，请导出当前进度。');if(done&&state.adviceInbox?.length){advisorItems=state.adviceInbox.slice();advisorPage=0;advisorModal(false);}else if(type!=='choice'&&(state.companyNews?.length||0)>newsCount)maybeAdvisor();return true;}catch(err){toast(err.message);return false;}}
let advisorItems=[],advisorPage=0,advisorReturn='report',activeAdvice=null;
function adviceActionMatches(a,type,data){return (['price','aircraft','route'].includes(a.type)&&type==='editRoute'&&data.id===a.route)||(a.type==='cabin'&&type==='cabin'&&data.id===a.plane)||(a.type==='hangar'&&['buildHangar','upgradeHangar'].includes(type))||(a.type==='finance'&&type==='loan')||(a.type==='capacity'&&type==='expand');}
function finishAdvice(key){AIR_ADVISOR.present(state,key);advisorItems=advisorItems.filter(a=>a.key!==key);activeAdvice=null;}
function retainAdvice(items,persist=true){state.adviceInbox||=[];for(const a of items)if(!AIR_ADVISOR.presented(state,a.key)&&!state.adviceInbox.some(x=>x.key===a.key))state.adviceInbox.push(a);if(persist)save();}

function maybeAdvisor(back='report'){if(simulationRunning)return false;const fresh=AIR_ADVISOR.fresh(state).filter(a=>!state.pending||a.priority>=95);if(!fresh.length)return false;retainAdvice(fresh);advisorItems=fresh;advisorPage=0;advisorReturn=back;advisorModal(false);return true;}
function advisorModal(refresh=true){if(refresh){const fresh=AIR_ADVISOR.suggestions(state);advisorItems=[...new Map([...(state.adviceInbox||[]),...fresh].map(a=>[a.key,a])).values()];advisorPage=0;advisorReturn=E.simulationActive(state)||state.simulation?.status==='complete'?'batch':'report';}advisorPage=Math.max(0,Math.min(advisorPage,advisorItems.length-1));const a=advisorItems[advisorPage];if(a){AIR_ADVISOR.present(state,a.key);save();}showModal('经营顾问',a?`<div class="advisor-pager">${button('上一条','advisorPrev','',advisorPage===0?'disabled':'')}<span>${advisorPage+1} / ${advisorItems.length}</span>${button('下一条','advisorNext','',advisorPage===advisorItems.length-1?'disabled':'')}</div><span class="tag">${({operations:'运行清单',competition:'市场竞争',delivery:'飞机交付',city:'城市影响力',connection:'联程客流',milestone:'排名突破',network:'航网扩张',capacity:'基地容量',price:'定价策略',aircraft:'机型匹配',cabin:'客舱设计',hangar:'维修能力',finance:'现金管理',leases:'租约提醒',route:'航线恢复',market:'机队规划',disruption:'运行保障'})[a.type]}</span><h3 class="advisor-title">${esc(a.title)}</h3><p class="advisor-reason">${esc(a.text)}</p><p class="advisor-detail">${esc(a.detail)}</p><p class="advisor-disclaimer">预测基于当前游戏市场。查看建议不会自动购机、改价、改舱或建设机库。</p><div class="form-actions">${button('关闭','closeModal')}${button('经营汇总','advisorReport')}${button(({delivery:'安排飞机',hangar:'查看机库建设',finance:'查看资金',leases:'查看租约与航线',market:'比较机型',disruption:'查看延误与保障'})[a.type]||'查看并调整','advisorOpen','arrow','','primary')}</div>`:`<p>目前没有明显需要调整的经营事项。继续关注客流、机队利用率与现金储备。</p><div class="form-actions">${button('返回','closeModal')}</div>`,'消息展示一次，无需标记已读 · 可随时关闭，其他消息仍保留');}
function openAdvisorSuggestion(){const a=advisorItems[advisorPage];if(!a)return;retainAdvice([a]);activeAdvice=a;if(a.type==='operations'){operationsModal([a]);return;}if(a.type==='competition'){trafficPanel('markets',0);return;}if(a.type==='city'){setView('company');return;}if(a.type==='milestone'){setView('ranking');return;}if(a.type==='connection'){networkPanel('flows',0);return;}if(a.type==='network'){networkBase=a.from||state.base;networkPanel('expand',0);return;}if(a.type==='capacity'){setView('company');return;}if(a.type==='disruption'){delayPanel();return;}if(a.type==='price'||a.type==='aircraft'||a.type==='route'){routeModal(a.route);if(a.price)$('#route-form').elements.price.value=a.price;if(a.plane)$('#route-form').elements.plane.value=a.plane;setRouteStage(2);routeQuote();}else if(a.type==='cabin'){cabinModal(a.plane);const f=$('#cabin-form');Object.entries(a.cabin).forEach(([k,v])=>f.elements[k].value=v);cabinQuote();cabinPanel(1);}else setView(({delivery:'fleet',hangar:'hangar',finance:'finance',leases:'fleet',market:'market'})[a.type]||'overview');}
let operationItems=[],operationPage=0,operationSize=2;
function operationsModal(notices=null,page=0){
 if(notices){operationItems=AIR_ADVISOR.operationList(notices);operationSize=window.innerHeight<500?1:layoutMode()==='wide'?4:2;for(const n of notices)AIR_ADVISOR.present(state,n.key);save();}
 operationPage=Math.max(0,Math.min(page,Math.ceil(operationItems.length/operationSize)-1));const visible=operationItems.slice(operationPage*operationSize,(operationPage+1)*operationSize);
 showModal('延误保障与运力清单',`<p>已自动执行保障。${operationItems.length} 项按航线汇总，无需逐个城市确认。</p><div class="operations-list">${visible.map(g=>`<article class="notice"><strong>${esc(E.ap(g.from).city)} ${g.from} ⇄ ${esc(E.ap(g.to).city)} ${g.to} · 第 ${g.weekStart===g.week?g.week:g.weekStart+'–'+g.week} 周</strong>${g.delayed?`<p>${g.delayed} 班延误 · 改签 ${g.rebooked} 人 · 等待 ${g.waiting} 人 · 退款 ${g.refund} 人</p><small>同航路班次密度和剩余运力越大，保障效果越好。</small>`:''}${g.tight?`<p>运力偏紧：第 ${g.peakWeek} 周客座率 ${(g.peakLoad*100).toFixed(0)}%，当周 ${g.frequencies} 次往返。可比较加班或增派飞机。</p>`:''}</article>`).join('')}</div><div class="advisor-pager">${button('上一页','operationPage','','data-delta="-1" '+(operationPage===0?'disabled':''))}<span>${operationItems.length?operationPage+1:0} / ${Math.max(1,Math.ceil(operationItems.length/operationSize))}</span>${button('下一页','operationPage','','data-delta="1" '+((operationPage+1)*operationSize>=operationItems.length?'disabled':''))}</div><div class="form-actions">${button('关闭','closeModal')}${button('延误保障','delayPolicy','shield')}${button('安排航线','navigate','route','data-target="routes"','primary')}</div>`,'连续经营结束后集中提醒 · 资金、班次均未自动增加');
}
function advanceLabel(){return state.pending?'处理待办':E.simulationActive(state)?'继续模拟':'经营下一周';}
function advanceControls(){if(simulationRunning)return `<div class="advance-actions"><button class="btn primary" disabled>经营中 ${state.simulation.completed}/${state.simulation.target} 周</button>${button('暂停','pauseBatch','clock','','batch-trigger')}</div>`;return `<div class="advance-actions">${button(advanceLabel(),'advance','arrow',state.bankrupt?'disabled':'','primary')}${button('快进 5 周','quickAdvance','clock',`aria-label="直接连续经营 5 周" ${state.bankrupt?'disabled':''}`,'batch-trigger')}</div>`;}
function finishOperating(weeks=1){const fresh=AIR_ADVISOR.fresh(state);if(fresh.length)retainAdvice(fresh);const operations=fresh.filter(a=>a.type==='operations');if(operations.length){operationsModal(operations);return;}toast(`已完成 ${weeks} 周经营${fresh.length?' · 有 '+fresh.length+' 条新消息，可在经营顾问查看':''}`);}
function retirementModal(id){const p=state.fleet.find(p=>p.id===id);if(!p?.retired)return;const q=E.retirementQuote(state,id);$('#toast').classList.remove('show');showModal('飞机退役 · 接续原航线',`<p><strong>${esc(E.modelName(p.model))} · B-YS${String(p.id).padStart(3,'0')}</strong><br>机龄 ${(p.age/52).toFixed(1)} 年，已达到游戏设定的 25 年退役线。</p><div class="quote"><div><small>替代飞机</small>${q.used?'二手':'全新'} ${esc(E.modelName(q.model))}<small>${q.used?'原机型已停产；提供 '+q.age/52+' 年机龄二手机':'机龄 0 年'} · ${q.delivery} 周后交付</small></div><div><small>总计</small>${money(q.total)}<small>机价 ${money(q.price)} + 服务配置 ${money(q.fitout)}${q.mortgage?' + 原机抵押结清 '+money(q.mortgage):''}</small></div></div><p>自动接手 ${q.routes} 条原配机计划，保留基地、舱位、班次、票价和手动时刻。交付前暂停，交付后恢复；原已暂停航线保持暂停。</p>${state.cash<q.total?'<p class="negative">现金不足，可暂缓后到财务中心融资，再从机队中购买替代机。</p>':''}<div class="form-actions">${button('暂缓购买','deferRetirement','','data-id="'+id+'"')}${button('购买并自动接续','replaceRetired','','data-id="'+id+'" '+(state.cash<q.total?'disabled':''),'primary')}</div>`,'退役属于特殊经营事项；处理后连续模拟自动继续。');}
function maybeRetirement(){E.retireAgedPlanes(state);const p=E.pendingRetirements(state)[0];if(!p)return false;save();retirementModal(p.id);return true;}
function resolveRetirement(type,id){if(!act(type,{id},type==='replaceRetired'?'替代机已订购，交付后自动接续原航线':'已保留原航线，可稍后在机队中处理'))return;if(maybeRetirement())return;if(E.simulationActive(state))runSimulation();else if(retirementResumeSingle){retirementResumeSingle=false;advanceDirect();}else if(state.pending)story();}
function advanceDirect(){if(simulationRunning)return;if(E.simulationActive(state)){runSimulation();return;}if(maybeRetirement()){retirementResumeSingle=true;return;}if(state.pending){resumeSingleAfterChoice=true;story();return;}try{closeModal();E.advance(state);const notice=AIR_ADVISOR.operationNotice?.(state);if(notice)retainAdvice([notice],false);save();render();if(maybeRetirement())return;if(state.pending)story();else if(state.bankrupt||saveError)weeklyReport();else finishOperating();}catch(e){toast(e.message);}}
function resolveOperatingChoice(index){const completed=state.simulation?.status==='complete'&&state.simulation.endDate===state.date?state.simulation.completed:0;if(act('choice',{index},'决策已执行，结果已记入公司纪事')){if(E.simulationActive(state))runSimulation();else if(resumeSingleAfterChoice){resumeSingleAfterChoice=false;advanceDirect();}else finishOperating(completed||1);}}
function quickAdvance(weeks=5){if(simulationRunning)return;try{resumeSingleAfterChoice=false;retirementResumeSingle=false;if(!E.simulationActive(state)){E.startSimulation(state,weeks);save();}runSimulation();}catch(e){toast(e.message);}}
function batchPanel(){const b=state.simulation;if(E.simulationActive(state)){batchReport();return;}showModal('连续模拟经营',`<p>按当前机队、航线与服务设置逐周经营。每周自动存档；已设置的延误保障持续自动执行，其他需要选择的经营事件会暂停。</p><div class="batch-choices">${button('模拟 5 周','startBatch','clock','data-weeks="5"','primary')}${button('模拟 10 周','startBatch','clock','data-weeks="10"','primary')}</div><p class="muted">暂停后可以调整经营方案，再继续剩余周数。连续模拟不会自动代选剧情。</p>${b?button('查看上次模拟汇总','batchReport','chart'):''}<div class="form-actions">${button('返回','closeModal')}</div>`,'从日常运营中抬起头，看看更远的未来。');}
function batchReport(tab='summary'){if(!state.simulation){batchPanel();return;}settlementReport('batch',tab);}
function runSimulation(){if(simulationRunning||!E.simulationActive(state))return;resumeOnNoticeClose=false;closeModal();if(maybeRetirement()){render();return;}if(state.pending){render();story();return;}simulationRunning=true;render();const tick=()=>{if(!simulationRunning)return;try{E.stepSimulation(state);const notice=AIR_ADVISOR.operationNotice?.(state);if(notice)retainAdvice([notice],false);save();if(E.pendingRetirements(state).length||state.pending||state.bankrupt||state.simulation?.status==='paused'||!E.simulationActive(state)||saveError)simulationRunning=false;if(saveError)E.pauseSimulation(state,'save');if(simulationRunning){document.querySelectorAll('.advance-actions').forEach(el=>el.innerHTML=advanceControls());simulationTimer=setTimeout(tick,16);}else{render();if(maybeRetirement())return;if(state.pending)story();else if(state.bankrupt||saveError)batchReport();else if(E.simulationActive(state)&&['lease','disruption'].includes(state.simulation.reason)){resumeOnNoticeClose=true;showModal(state.simulation.reason==='lease'?'租赁合同出现变更':'本周出现严重延误',`<p>${state.simulation.reason==='lease'?'本周出现租约收回或到期通知；已发生的退回与退款按合同自动处理，详情已记录在公司纪事。':'延误造成的费用与旅客影响已计入本周结果，可在旅客服务中设置自动保障。'}</p><p>关闭提示后，自动继续剩余 ${state.simulation.target-state.simulation.completed} 周。</p><div class="form-actions">${button('暂停并查看汇总','pauseBatch')}${button('知道了，自动继续','closeModal','','','primary')}</div>`);}else if(E.simulationActive(state))batchReport();else finishOperating(state.simulation.completed);}}catch(err){simulationRunning=false;E.pauseSimulation(state,'error');save();render();batchReport();toast(err.message);}};simulationTimer=setTimeout(tick,16);}
function stopSimulation(){resumeOnNoticeClose=false;clearTimeout(simulationTimer);simulationTimer=null;if(simulationRunning){simulationRunning=false;E.pauseSimulation(state);save();render();}}
function layoutMode(){return window.innerWidth<=700||window.innerHeight<=500?'compact':window.innerWidth<1100?'medium':'wide';}
function pageSize(key,kind='table',mode=layoutMode()){if(key==='routeTimetable')return mode==='compact'?(window.innerHeight<=700?1:2):3;if(kind==='routes')return mode==='compact'?1:mode==='medium'?2:4;return kind==='cards'?(mode==='compact'?1:mode==='medium'?2:3):mode==='compact'?(key==='ranking'?(window.innerHeight<=500?2:window.innerHeight<=700?3:4):4):8;}
function pageItems(items,key,kind='table'){const size=pageSize(key,kind),count=Math.max(1,Math.ceil(items.length/size));pages[key]=Math.min(Math.max(0,pages[key]||0),count-1);pageMeta[key]={count,total:items.length,size,kind};return items.slice(pages[key]*size,(pages[key]+1)*size);}

function pager(key){const m=pageMeta[key];return `<div class="pagination" aria-label="列表分页"><span>${m.total} 项 · 第 ${(pages[key]||0)+1} / ${m.count} 页</span><div>${button('上一页','page','',`data-key="${key}" data-delta="-1" ${!pages[key]?'disabled':''}`)}${button('下一页','page','',`data-key="${key}" data-delta="1" ${(pages[key]||0)>=m.count-1?'disabled':''}`)}</div></div>`;}
function quickTools(){return `<nav class="quick-tools" aria-label="经营调整">${button('航线','newRoute','route')}${button('排班','navigate','clock','data-target="schedule"')}${button('采购','navigate','plane','data-target="market"')}${button('服务','navigate','star','data-target="service"')}${button('顾问','advisor','info')}</nav>`;}
function blueDream(){showModal('致每一个有蓝天梦的人',`<div class="dream-photo"><span>YOUR SKY. YOUR STORY.</span></div><div class="dream-copy"><h3>把望向天空的那一眼，<br>变成自己的航线图。</h3><p>也许你记得第一次坐在舷窗边，看城市一点点变小；也许你只是喜欢抬头，猜一架飞机正飞向哪里。</p><p>在这里，你可以为一家航空公司取名字，选择它出发的城市，再把一条条航线连向世界。让每一次起飞都可靠，让每一位旅客都被认真对待。</p><p class="dream-signature">第一张登机牌，写着你的梦想。</p></div><div class="form-actions">${button('回到我的天空','closeModal','arrow','','primary')}</div>`,'打造全球最佳航司 · 写给未来的航司创始人',true);}
function setView(v){view=v;closeModal();render();$('.content')?.scrollTo({top:0});}function render(){calendarRemember();if(!state){renderRecovery();return;}const current=NAV.find(x=>x[0]===view)?.[2]||({market:'飞机采购',settings:'存档与设置',sources:'资料与规则'}[view]);const rank=E.rankings(state).findIndex(x=>x.player)+1;
$('#app').innerHTML=`<div class="app-layout"><aside class="sidebar"><div class="brand"><div><strong>打造全球最佳航司</strong><small>SKYBOUND AIRLINES</small></div></div><div class="nav-label">AIRLINE MANAGEMENT</div><nav class="nav" aria-label="主导航">${NAV.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}" title="${label}">${ic(icon,18)}<span>${label}</span>${id==='events'&&state.pending?'<b class="badge">1</b>':''}</button>`).join('')}</nav><div class="nav-label">WORKSPACE</div><nav class="nav secondary"><button data-view="settings">${ic('settings',18)}<span>存档与设置</span></button><button data-view="sources">${ic('book',18)}<span>资料与规则</span></button></nav><div class="sidebar-bottom"><div class="helpbox"><strong>下一站，世界一流。</strong><p>从第一条航线，到连接整个世界。</p><button data-action="guide">经营指南 ${ic('arrow',13)}</button></div><div class="profile"><span class="avatar">${esc(state.name.slice(0,1))}</span><div><strong>${esc(state.name)}</strong><small>${E.ap(state.base).city}基地 · 董事长</small></div></div></div></aside><main class="main-shell" data-page="${view}"><header class="topbar"><div class="crumb">航空经营模拟 ${ic('chevron',11)} <span>${current}</span></div><div class="top-actions"><span class="saved"><i class="dot"></i>${saveError?'未自动保存':'本机自动存档'}</span><div class="datebox">${ic('calendar',15)}<span class="mono">${dateText()}</span><small>W${String(state.week).padStart(2,'0')}</small></div><i class="divider"></i>${advanceControls()}</div></header><div class="mobile-page-switch"><label>功能页面<select id="mobile-view" aria-label="切换功能页面">${[...NAV,['settings','','存档与设置'],['sources','','资料与规则']].map(([id,icon,label])=>`<option value="${id}" ${view===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="content" id="workspace-content">${maintenanceNotice()}${state.bankrupt?'<div class="danger-banner">公司现金缺口超过 1,000 万元，已经停止运营。可在设置中导出存档或重新开始。</div>':state.cash<10?'<div class="danger-banner">现金储备偏低。建议检查亏损航线、降低扩张支出，或申请融资。</div>':''}${({overview:overview,routes:routes,schedule:timetable,insights:insights,fleet:fleet,market:market,service:service,events:events,finance:finance,ranking:ranking,company:company,hangar:hangar,settings:settings,sources:sources}[view]||overview)()}<div class="mobile-extra">${['fleet','market','service','events','finance','hangar','ranking','company','settings','sources'].map(v=>button(({fleet:'机队',market:'采购',service:'服务',events:'动态',finance:'财务',hangar:'机库',ranking:'排行榜',company:'公司',settings:'存档',sources:'规则'})[v],'navigate','',`data-target="${v}"`)).join('')}</div><footer class="footer-note"><span>${esc(state.name)} · 中国民营航空公司 · 全球综合排名 #${rank}</span><span>经营与外交剧情为模拟设定 · 非实时航空数据</span></footer></div><div class="command-dock"><div><small>W${String(state.week).padStart(2,'0')} · 可用现金</small><strong>${money(state.cash)}</strong></div>${advanceControls()}</div></main></div>`;applyPanorama();calendarRestore();}
function maintenanceNotice(){const a=state.maintenanceAdvice;if(!a||state.week>a.week+4)return '';return `<div class="maintenance-notice"><div><strong>机务提醒</strong><p>${esc(a.text)}</p></div>${button(a.kind==='funds'?'查看资金':'管理机库','navigate','tool',`data-target="${a.kind==='funds'?'finance':'hangar'}"`)}</div>`;}
function head(eyebrow,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-buttons">${actions}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,unit,foot,icon,positive])=>`<div class="stat"><div class="stat-top">${label}<span class="sicon">${ic(icon,15)}</span></div><div class="stat-value">${value}<em>${unit}</em></div><div class="stat-foot"><span class="${positive?'positive':''}">${positive?'↗ ':''}${foot}</span></div></div>`).join('')}</div>`;}
function overview(){const report=state.lastReport,rs=state.routes.filter(r=>r.active),rank=E.rankings(state).findIndex(r=>r.player)+1;let flights=[];for(const p of state.fleet.filter(p=>E.planeAvailable(state,p)))try{flights.push(...E.schedulePlan(state,p.id).flatMap(t=>t.segments.map(l=>({...l,model:p.model,base:t.base}))));}catch{}flights.sort((a,b)=>a.dep-b.dep);const tasks=[state.pending?['董事会等待你的决定',state.pending.title,'story','处理待办']:['本周航班计划已准备',`${routeCount(rs)} 条在营航线 · ${flights.length} 个计划航段`,'navigate','检查排班','schedule'],state.fleet.some(p=>p.condition<65)?['机队需要照料','留意维护状态，安排检修再出发。','navigate','查看机队','fleet']:['为下一程做准备','比较市场需求，再决定下一条航线。','navigate','寻找机会','insights']];return `<section class="overview-hero"><div><span class="eyebrow">${esc(state.name)} · FLIGHT OPERATIONS</span><h1>让每一次起飞，都有远方。</h1><p>${E.ap(state.base).city}始发 · 全球排名 #${rank} · 你的天空，正在延伸</p>${button('致有蓝天梦的人','blueDream','book')}</div><span class="hero-coordinate">${state.base}<small>${E.ap(state.base).lat.toFixed(2)}° N</small></span></section>${stats([['可用现金',money(state.cash),'',report?`周利润 ${money(report.profit,true)}`:'可用于运营与扩张的现金','wallet'],['在役飞机',state.fleet.filter(p=>!p.retired&&!p.delivery).length,'架',`${state.fleet.filter(p=>p.delivery).length} 架待交付`,'plane'],['运营航线',routeCount(rs),'条',`覆盖 ${new Set(rs.flatMap(E.routePoints)).size} 座机场`,'route'],['旅客口碑',state.rep.toFixed(1),'/100',`可靠性 ${state.reliable.toFixed(1)}%`,'star']])}${quickTools()}<div class="workspace-tabs" role="tablist" aria-label="运营总览分区">${[['dispatch','本周运营'],['network','航线地图'],['news','世界动态']].map(([id,label])=>`<button role="tab" aria-selected="${dashboardTab===id}" data-action="dashboardTab" data-tab="${id}">${label}</button>`).join('')}</div><div class="briefing-workspace">${dashboardTab==='dispatch'?`<div class="briefing-grid"><section class="panel departure-board"><div class="panel-head"><h2>本周起飞计划</h2>${button('完整排班','navigate','clock','data-target="schedule"','tiny')}</div>${flights.slice(0,3).map(l=>`<div class="departure-row"><time>${E.localClock(state,l.base,l.dep,l.a).time}<small>周${E.localClock(state,l.base,l.dep,l.a).weekday}</small></time><div><strong>${l.a} <span>→</span> ${l.b}</strong><small>${E.ap(l.a).city}至${E.ap(l.b).city} · ${E.modelName(l.model)}</small></div><span class="status-light">已计划</span></div>`).join('')||'<div class="empty">先为可用飞机规划一条航线。</div>'}</section><aside class="panel duty-brief"><div class="panel-head"><h2>运营简报</h2><span class="tag">W${state.week}</span></div>${tasks.map(([t,d,a,b,target])=>`<div class="brief-task"><div><h3>${esc(t)}</h3><p>${esc(d)}</p></div>${button(b,a,'arrow',target?`data-target="${target}"`:'','tiny')}</div>`).join('')}${button('查看经营周报','report','chart','','brief-report')}</aside></div>`:dashboardTab==='network'?`<section class="panel map-panel"><div class="panel-head"><h2>连接你与世界</h2><div class="tabs">${['china','world'].map(id=>`<button data-action="map" data-mode="${id}" class="${mapMode===id?'active':''}">${id==='china'?'中国':'全球'}</button>`).join('')}</div></div>${map(false)}<div class="map-legend"><span><i class="map-key base"></i>运营基地</span><span><i class="map-key"></i>在营航线</span>${button('展开全景','panorama','globe','','tiny')+button('规划航线','newRoute','plus','','tiny')}</div></section>`:`<section class="panel padded"><div class="card-title"><h2>世界的变化，航线的机会</h2>${button('完整日历','navigate','','data-target="events"','tiny')}</div>${E.activeEvents(state).slice(0,2).map(e=>eventMini(e)).join('')||'<p>本周市场平稳。</p>'}${calendarUpcoming().slice(0,1).map(e=>eventMini(e,true)).join('')}</section>`}</div>`;}

function project(lon,lat){return AIR_MAP.project(lon,lat,mapMode);}
function map(large){let shapes='';const world=window.AIR_WORLD||[];for(const poly of world){let pts=poly.map(p=>project(p[0],p[1]));if(mapMode==='world'){let runs=[],run=[];for(let i=0;i<pts.length;i++){if(i&&Math.abs(pts[i][0]-pts[i-1][0])>500){if(run.length>2)runs.push(run);run=[];}run.push(pts[i]);}if(run.length>2)runs.push(run);shapes+=runs.map(a=>`<path class="land" d="M${a.map(p=>p.map(n=>n.toFixed(1)).join(',')).join('L')}Z"/>`).join('');}else shapes+=`<path class="land" d="M${pts.map(p=>p.map(n=>n.toFixed(1)).join(',')).join('L')}Z"/>`;}
const borders=(window.AIR_BORDERS||[]).flatMap(line=>AIR_MAP.boundaryPaths(line,mapMode)).map(d=>`<path class="country-border" d="${d}"/>`).join('');const projected=D.airports.map(a=>({...a,xy:project(a.lon,a.lat)})).filter(a=>a.xy[0]>0&&a.xy[0]<1000&&a.xy[1]>0&&a.xy[1]<450);let routepaths=state.routes.flatMap(r=>E.routeLegs(r).map(l=>({...r,...l}))).map(r=>AIR_MAP.curves(E.ap(r.from),E.ap(r.to),mapMode).map(c=>`<path class="flight-path ${r.active?'':'paused'}" d="${c.d}"><title>${E.ap(r.from).city} → ${E.ap(r.to).city}${r.active?'':' · 暂停'}</title></path>${r.active?`<circle class="flight-dot" r="2.3" fill="#608c64"><animateMotion dur="${7+r.id%4}s" repeatCount="indefinite" path="${c.d}"/></circle>`:''}`).join('')).join('');let connected=new Set(state.routes.flatMap(E.routePoints));let labels=new Set(mapMode==='china'?['HGH','PKX','PVG','CAN','TFU','KMG','URC','HRB','XIY','HKG','NRT','BKK','ICN','SYX']:['HGH','LHR','CDG','DXB','SIN','SYD','LAX','JFK','JNB','GRU','NRT']);return `<div class="map-inline-tools">${button('−','mapZoom','','data-factor="0.67" aria-label="缩小地图"')}${button('+','mapZoom','','data-factor="1.5" aria-label="放大地图"')}${button('查看全部','mapFit')}<small>拖动 · 双指缩放</small></div><div class="world-map ${large?'large':''}"><svg viewBox="0 0 1000 450" role="img" aria-label="航线网络地图，美洲在东侧，欧洲与非洲在西侧"><defs><pattern id="mapdots" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".55" fill="#dce5d7"/></pattern></defs><rect width="1000" height="450" fill="url(#mapdots)" opacity=".3"/>${[60,150,240,330,420].map(y=>`<path class="graticule" d="M0 ${y}H1000"/>`).join('')}${shapes}<g class="country-borders" aria-label="国界线">${borders}</g>${routepaths}${projected.map(a=>{let base=state.hubs.some(h=>h.code===a.code),active=connected.has(a.code),[x,y]=a.xy;return `<g class="destination" data-action="airport" data-code="${a.code}" tabindex="0" role="button" aria-label="${a.city} ${a.code}"><title>${a.city} ${a.name} · ${a.code}</title>${base?`<circle cx="${x}" cy="${y}" r="10" fill="#c8aa6e" opacity=".12"/><circle cx="${x}" cy="${y}" r="6.5" fill="none" stroke="#bb9c63" stroke-width=".7"/>`:''}<circle cx="${x}" cy="${y}" r="${base?3.4:active?3:1.8}" fill="${base?'#b8995b':active?'#4e7f58':'#bfcdb7'}"/>${(labels.has(a.code)||active)?`<text x="${x+8}" y="${y+(a.code==='PVG'?14:-6)}" class="map-label ${base?'base':''}">${esc(a.city)}${base?' · 基地':''}</text>`:''}</g>`}).join('')}</svg></div>`;}
let panoramaView={x:0,y:0,w:1000,h:450},panoramaDrag=null,panoramaDragged=false;
function applyPanorama(){const svg=$('.panorama-map svg')||$('.world-map svg');if(!svg)return;svg.setAttribute('viewBox',`${panoramaView.x} ${panoramaView.y} ${panoramaView.w} ${panoramaView.h}`);if($('#map-zoom-level'))$('#map-zoom-level').textContent=Math.round(1000/panoramaView.w*100)+'%';declutterMap(svg);}
function zoomPanorama(factor,airport=null){const v=panoramaView,w=Math.max(125,Math.min(1000,v.w/factor)),h=w*.45,center=airport?AIR_MAP.project(airport.lon,airport.lat):[v.x+v.w/2,v.y+v.h/2];panoramaView={x:Math.max(0,Math.min(1000-w,center[0]-w/2)),y:Math.max(0,Math.min(450-h,center[1]-h/2)),w,h};applyPanorama();}
function focusMapAirport(code){const a=E.ap(code);if(!a)return;panoramaView.w=1000;zoomPanorama(4,a);$('#panorama-airport').value=code;$('#panorama-info').textContent=`${a.country} · ${a.city} · ${a.code} · ${state.routes.filter(r=>E.routePoints(r).includes(code)).length} 条航线经过此机场`;}
function panorama(){mapMode='world';panoramaView={x:0,y:0,w:1000,h:450};showModal('全球航线全景',`<div class="panorama-toolbar"><label>查找机场<select id="panorama-airport" aria-label="在全景地图查找机场"><option value="">选择城市或机场</option>${D.airports.slice().sort((a,b)=>a.city.localeCompare(b.city,'zh-CN')).map(a=>`<option value="${a.code}">${esc(a.city)} · ${a.code} · ${esc(a.country)}</option>`).join('')}</select></label><div class="panorama-tools">${button('−','mapZoom','','data-factor="0.67" aria-label="缩小地图"')}<span id="map-zoom-level">100%</span>${button('+','mapZoom','','data-factor="1.5" aria-label="放大地图"')}${button('查看全部','mapFit')}${button('定位基地','mapBase')}</div></div><div class="panorama-map">${map(true)}</div><div class="panorama-caption"><span>西侧 · 欧洲 / 非洲</span><span>亚洲 · 太平洋</span><span>东侧 · 美洲</span></div><p id="panorama-info">${routeCount(state.routes)} 条航线 · ${state.hubs.length} 个基地 · ${D.airports.length} 座机场。拖动地图查看细节，点击机场查看信息。</p><div class="form-actions"><span class="map-disclaimer">航线示意图；实际航程按距离计算。</span>${button('收起全景','closeModal','close','','primary')}</div>`,'美洲航线向东跨太平洋，欧洲和非洲位于西侧。',true);$('.modal').classList.add('panorama-modal');applyPanorama();}
function declutterMap(svg){const v=panoramaView,rect=svg.getBoundingClientRect(),scale=Math.min(rect.width/v.w,rect.height/v.h);if(!scale)return;const boxes=[],texts=[...svg.querySelectorAll('.map-label')].sort((a,b)=>Number(b.classList.contains('base'))-Number(a.classList.contains('base')));for(const t of texts){t.style.fontSize=(13/scale)+'px';const x=Number(t.getAttribute('x')),y=Number(t.getAttribute('y')),box={x:x*scale,y:y*scale-13,w:t.textContent.length*13+8,h:18};const flip=box.x+box.w>(v.x+v.w)*scale;t.style.textAnchor=flip?'end':'start';if(flip)box.x-=box.w;const outside=box.x<v.x*scale||box.x+box.w>(v.x+v.w)*scale||box.y<v.y*scale||box.y+box.h>(v.y+v.h)*scale,overlap=boxes.some(b=>box.x<b.x+b.w&&box.x+box.w>b.x&&box.y<b.y+b.h&&box.y+box.h>b.y);t.style.visibility=outside||overlap?'hidden':'visible';if(!outside&&!overlap)boxes.push(box);}}
const mapPointers=new Map();let pinchDistance=0;
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('.world-map svg');if(!svg)return;panoramaDragged=false;mapPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});panoramaDrag={id:e.pointerId,x:e.clientX,y:e.clientY,start:{...panoramaView},svg};if(mapPointers.size===2){const [a,b]=[...mapPointers.values()];pinchDistance=Math.hypot(a.x-b.x,a.y-b.y);}});
document.addEventListener('pointermove',e=>{const d=panoramaDrag;if(!d||!mapPointers.has(e.pointerId))return;mapPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(mapPointers.size===2){const [a,b]=[...mapPointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(pinchDistance>0)zoomPanorama(distance/pinchDistance);pinchDistance=distance;panoramaDragged=true;return;}const dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.hypot(dx,dy)<5&&!panoramaDragged)return;panoramaDragged=true;d.svg.setPointerCapture(e.pointerId);const rect=d.svg.getBoundingClientRect(),scale=Math.min(rect.width/d.start.w,rect.height/d.start.h);panoramaView.x=Math.max(0,Math.min(1000-panoramaView.w,d.start.x-dx/scale));panoramaView.y=Math.max(0,Math.min(450-panoramaView.h,d.start.y-dy/scale));applyPanorama();});
function endMapPointer(e){mapPointers.delete(e.pointerId);pinchDistance=0;if(mapPointers.size&&panoramaDrag){const [id,a]=[...mapPointers.entries()][0];panoramaDrag={...panoramaDrag,id,x:a.x,y:a.y,start:{...panoramaView}};}else panoramaDrag=null;}
document.addEventListener('pointerup',endMapPointer);document.addEventListener('pointercancel',endMapPointer);
document.addEventListener('wheel',e=>{if(!e.target.closest('.world-map svg'))return;e.preventDefault();zoomPanorama(e.deltaY<0?1.15:1/1.15);},{passive:false});
window.addEventListener('resize',()=>requestAnimationFrame(applyPanorama));
function eventMini(e,future=false){return `<div class="event-item"><div class="event-symbol ${future?'amber':''}">${ic(future?'calendar':'sun',15)}</div><div><h4>${esc(e.title)}</h4><p>${esc(e.desc||'提前布局运力，准备迎接客流变化。')}</p><div class="event-impact">${future?'提前规划':e.closed?'相关航线暂停':e.demand>1?`相关市场客流 +${Math.round((e.demand-1)*100)}%`:'留意运营成本变化'}</div>${future?`<div class="event-date">${e.when}</div>`:''}</div></div>`;}
function routeCards(rows){return rows.length?`<div class="route-card-grid">${rows.map(r=>{const p=state.fleet.find(p=>p.id===r.plane),e=E.estimate(state,r);return `<article class="route-card"><div class="card-title"><button class="route-title" data-action="editRoute" data-id="${r.id}" aria-label="调整${E.ap(r.from).city}至${E.ap(r.to).city}航线">${E.ap(r.from).city} ⇄ ${E.ap(r.to).city}</button><span class="tag ${r.active?'':'amber'}">${r.active?'运营中':'已暂停'}</span></div><p>${r.from} ⇄ ${r.to} · ${r.via?'经 '+E.ap(r.via).city:'直飞'} · <strong>本机每周 ${r.freq} 次往返</strong> · 本线合计 ${routeStatus(r.from,r.to).freq} 次 / ${routeStatus(r.from,r.to).planes} 架</p><p>${p?esc(E.modelName(p.model))+' · B-YS'+String(p.id).padStart(3,'0'):'待指派飞机'}</p><p>预计客座率 ${pct(e.load)} · 周贡献 <span class="${e.profit>=0?'positive':'negative'}">${money(e.profit,true)}</span></p><p>本地 ${e.localPax??e.pax} · 转机 ${e.transferPax||0} 人次 / 周</p><div class="route-card-actions">${button('调整班次 / 配机','editRoute','settings',`data-id="${r.id}"`,'primary')}${button('增派飞机','addRoutePlane','plus',`data-from="${r.from}" data-to="${r.to}"`)}${button('航线时刻表','routeSchedule','clock',`data-from="${r.from}" data-to="${r.to}"`)}${button('舱位管理','routeCabins','seat',`data-from="${r.from}" data-to="${r.to}"`)}</div><details class="route-more"><summary>更多操作</summary><div class="route-actions">${button('全部执飞飞机','routeGroup','fleet',`data-from="${r.from}" data-to="${r.to}"`)}${button(r.active?'暂停航线':'恢复航线','toggle','',`data-id="${r.id}"`)}${button('关闭航线','closeRoute','',`data-id="${r.id}"`,'danger')}</div></details></article>`;}).join('')}</div>`:'<div class="empty">还没有开通航线。为已交付的飞机规划第一条航线。</div>';}
let managedPlane=0,managedRoutePage=0;
function planeRoutes(id,page=0){managedPlane=id;managedRoutePage=page;const p=state.fleet.find(p=>p.id===id);if(!p)return;const rows=E.prioritizedRoutes(state,state.routes.filter(r=>r.plane===id)),index=Math.max(0,Math.min(page,rows.length-1));managedRoutePage=index;showModal('管理这架飞机的航线',`<p>${esc(E.modelName(p.model))} · B-YS${String(id).padStart(3,'0')} · ${rows.length} 条航线</p><div class="advisor-pager">${button('上一条','planeRoutePage','','data-delta="-1" '+(index===0?'disabled':''))}<span>${rows.length?index+1:0} / ${rows.length}</span>${button('下一条','planeRoutePage','','data-delta="1" '+(index>=rows.length-1?'disabled':''))}</div>${routeCards(rows.slice(index,index+1))}<div class="form-actions">${button('返回','closeModal')}${button('新增航线','newRoute','plus',`data-plane="${id}" ${!E.planeAvailable(state,p)?'disabled':''}`,'primary')}</div>`,'选择现有航线修改班次、票价、配机或时刻；也可把这架飞机增派到已有航线。');}

let networkPage=0,networkSection='summary',networkBase='';
function networkPanel(section=networkSection,page=networkPage){
 networkSection=section;networkPage=page;networkBase=state.hubs.some(h=>h.code===networkBase)?networkBase:state.base;
 const n=E.networkForecast(state),flows=new Map();for(const c of n.connections){const key=[c.from,c.hub,c.to].join('-'),f=flows.get(key)||{...c,pax:0,revenue:0};f.pax+=c.pax;f.revenue+=c.revenue;flows.set(key,f);}
 const items=section==='hubs'?n.hubs:section==='flows'?[...flows.values()].sort((a,b)=>b.pax-a.pax):section==='expand'?E.expansionOptions(state,networkBase):[];networkPage=Math.max(0,Math.min(page,items.length-1));const item=items[networkPage];
 let body='',action='';
 if(section==='summary')body=`<div class="quote network-metrics"><div><small>实际覆盖机场</small><strong>${n.cities}</strong></div><div><small>预计转机行程 / 周</small><strong>${n.transferPax.toLocaleString()}</strong></div><div><small>联程票收入 / 周</small><strong>${money(n.transferRevenue)}</strong></div></div><p>航线越丰富，旅客越愿意选择同一家航司。当前覆盖带来的知名度增益为 <strong>${((n.awareness-1)*100).toFixed(1)}%</strong>，增长会逐渐放缓。</p><p>班次更密可提升便利度；真正的转机客流还需要两班时刻衔接和同舱余座。收入已分摊到两条航线，只计算一次联程票。</p>${button('查看全球客流与竞争','traffic','chart')}`;
 else if(!item)body=`<div class="empty">${section==='flows'?'目前没有可售的联程。请检查两段余座与时刻：国内留足60分钟、国际90分钟，最多等待8小时。过度绕行不会吸引旅客。':section==='expand'?'当前没有符合资质的未覆盖目的地，可检查国际资质或扩充基地。':'开通并运营航线后，这里会显示各机场的连接情况。'}</div>`;
 else if(section==='hubs')body=`<span class="tag">${item.role}</span><h3>${esc(E.ap(item.code).city)} · ${item.code}</h3><div class="quote network-metrics"><div><small>直接连接机场</small>${item.destinations}</div><div><small>预计转机行程 / 周</small>${item.pax.toLocaleString()}</div></div><p>更多可衔接的目的地，能为现有支线带来新客流。售罄或无法衔接的航班不会贡献转机订单。</p>`;
 else if(section==='flows'){body=`<span class="tag">${esc(E.ap(item.hub).city)}中转</span><h3>${esc(E.ap(item.from).city)} → ${esc(E.ap(item.to).city)}</h3><div class="quote network-metrics"><div><small>预计行程 / 周</small>${item.pax.toLocaleString()}</div><div><small>联程票收入 / 周</small>${money(item.revenue)}</div></div><p>顺路程度：实际航程为直线的 ${(item.detour||1).toFixed(2)} 倍；转机等待 ${item.wait} 分钟，总耗时约 ${((item.duration||0)/60).toFixed(1)} 小时。</p><p>客流同时占用 ${item.from} → ${item.hub} 与 ${item.hub} → ${item.to} 两段座位。可调整两段班次与时刻，扩大可售联程。</p>`;action=button('前段航线','editRoute','route',`data-id="${item.firstRoute}"`)+button('后段航线','editRoute','route',`data-id="${item.secondRoute}"`);}
 else {body=`<span class="tag">尚未覆盖 · ${item.plane?'现有机队可执行':'需安排运力'}</span><h3>${esc(E.ap(networkBase).city)} → ${esc(E.ap(item.to).city)}</h3><div class="quote network-metrics"><div><small>市场周需求</small>${item.demand.toLocaleString()}</div><div><small>可延伸的出行市场</small>${item.networkMarkets}</div></div><p>${item.km.toLocaleString()} km · 竞争${item.competition}。${item.plane?'已检查同基地飞机可执行每周3次往返。':'当前同基地飞机无法执行每周3次往返，请先购机、调机或释放时刻。'}</p><p class="muted">这是市场机会，实际销量仍受票价、时刻和余座限制。</p>`;action=item.plane?button('规划这条航线','networkPlan','plus',`data-from="${networkBase}" data-to="${item.to}" data-plane="${item.plane}"`,'primary'):button('查看机队','navigate','plane','data-target="fleet"');}
 showModal('枢纽与转机客流',`<div class="workspace-tabs network-tabs" role="tablist" aria-label="枢纽分析分区">${[['summary','概览'],['hubs','枢纽'],['flows','客流'],['expand','扩张']].map(([id,label])=>`<button role="tab" aria-selected="${section===id}" data-action="networkSection" data-section="${id}">${label}</button>`).join('')}</div>${section==='expand'?`<label class="field">出发基地<select id="network-base">${state.hubs.map(h=>`<option value="${h.code}" ${h.code===networkBase?'selected':''}>${esc(E.ap(h.code).city)} · ${h.code}</option>`).join('')}</select></label>`:''}<section class="network-detail">${body}</section><div class="form-actions network-footer">${items.length?`<div class="network-pager">${button('上一页','networkPage','',`data-delta="-1" ${networkPage===0?'disabled':''}`)}<span>${networkPage+1} / ${items.length}</span>${button('下一页','networkPage','',`data-delta="1" ${networkPage===items.length-1?'disabled':''}`)}</div>`:''}<div class="network-buttons">${button('返回','closeModal')}${action}</div></div>`,'按当前排班与市场估算 · 承运人次按登机次数统计');
}
function routes(){const rows=pageItems(E.prioritizedRoutes(state),'routes','routes');return `${head('NETWORK PLANNING','航线运营','待改派和暂停航线优先展示，便于补齐执飞计划。',button('枢纽分析','network','people')+button('客流竞争','traffic','chart')+button('展开全景','panorama','globe')+button(state.autoPricing?'自动定价：开':'自动定价：关','pricingPolicy','settings')+button('开通航线','newRoute','plus','','primary'))}<div class="workspace-tabs" role="tablist" aria-label="航网分区">${[['list','航线运营'],['map','全球地图']].map(([id,label])=>`<button role="tab" aria-selected="${networkTab===id}" data-action="networkTab" data-tab="${id}">${label}</button>`).join('')}</div>${networkTab==='list'?`<p class="route-list-summary">${routeCount(state.routes)} 条航线 · ${state.routes.length} 个配机计划（按飞机分别管理）</p>${pager('routes')}<section class="panel route-management">${routeCards(rows)}</section>`:`<section class="panel map-panel"><div class="panel-head"><h2>航线网络 · ${routeCount(state.routes)} 条</h2><div class="tabs"><button data-action="map" data-mode="china">中国</button><button data-action="map" data-mode="world">全球</button></div></div>${map(true)}<p class="map-legend">点击机场可规划航线；也可使用上方「开通航线」按钮。</p></section>`}`;}

function planeSVG(m){return `<div class="model-name maker-model"><strong>${esc(E.modelName(m))}</strong><span class="${m.fictional?'concept-label':''}">${m.fictional?`虚拟飞机 · ${m.releaseYear} 年上市（游戏设定）`:m.id.includes('ULR')?'超远程系列 · 提前开放':m.usedOnly?'成熟机型 · 二手交易':m.type+' · 自定义客舱'}</span></div>`;}

function fleet(){const rows=pageItems(E.prioritizedFleet(state).filter(p=>fleetFilter==='全部'||fleetFilter==='待交付'&&p.delivery||fleetFilter==='检修'&&p.maintenance||fleetFilter==='在役'&&!p.retired&&!p.delivery&&!p.maintenance),'fleet','cards');return `${head('FLEET MANAGEMENT','好飞机，是好航司的起点。','未安排航班的飞机优先展示，便于为新航线分配运力。',button('我的机库','navigate','tool','data-target="hangar"')+button('购置 / 租赁飞机','market','plus','','primary'))}<div class="filters">${['全部','在役','待交付','检修'].map(x=>`<button class="filter-btn ${fleetFilter===x?'active':''}" data-action="fleetFilter" data-filter="${x}">${x}</button>`).join('')}<small style="margin-left:auto">全天 24 小时可排班 · 每架飞机每周最多飞行 100 小时</small></div>${pager('fleet')}<div class="page-grid fleet-grid">${rows.map(p=>{const m=E.model(p.model),hours=E.usedHours(state,p.id),c=E.cabinOf(p),cs=E.cabinStats(m,c);return `<article class="aircraft-card"><div class="plane-render">${planeSVG(m)}</div><div class="card-body"><div class="card-title"><h3>${esc(E.modelName(m))}</h3><span class="tag ${p.delivery||p.maintenance?'amber':p.condition<55?'red':''}">${p.retired?'已退役 · 待替换':p.reposition?'调机中 · 1 周':p.delivery?`${p.delivery} 周后交付`:p.maintenance?`检修 ${p.maintenance} 周`:p.maintenanceBlocked?'检修待资金':p.condition<=65?'下周自动检修':!E.usedHours(state,p.id)?'未安排航班':'可运营'}</span></div><small>B-YS${String(p.id).padStart(3,'0')} · ${p.mode==='lease'?'经营性租赁':'自有资产'} · ${m.maker} · 驻地 ${E.planeBase(state,p)} · 机龄 ${(p.age/52).toFixed(1)} 年${E.pledged(state,p.id)?' · 已抵押':''}</small><div class="specs"><div><small>客舱座位</small>${cs.total} 席</div><div><small>参考航程</small>${m.range.toLocaleString()} km</div><div><small>周租金</small>${p.mode==='lease'&&!p.retired?money(E.weeklyLease(p)):'无'}</div></div><div class="cabin-summary"><span>经济 ${c.economy} · 商务 ${c.business} · 头等 ${c.first}</span><strong>舒适度 ${cs.comfort.toFixed(0)}</strong></div>${p.mode==='lease'?`<p class="lease-caption">出租方：${E.lessor(E.leaseInfo(p,state).lessor).name} · 模拟租赁公司${p.leaseContract?.recall?`<br>预计第 ${p.leaseContract.recall.dueWeek} 周收回，未用租金按日返还。`:''}</p>`:''}${p.mode==='lease'?button('查看租约','leaseDetail','book',`data-id="${p.id}"`):''}${button('调整舱位布局','cabin','seat',`data-id="${p.id}"`,'cabin-edit')}<div class="progress-row"><div><span>维护状态</span><span class="${p.condition<65?'negative':''}">${p.condition.toFixed(0)}%</span></div><div class="track"><i style="width:${p.condition}%"></i></div></div><div class="progress-row"><div><span>计划利用率</span><span>${hours.toFixed(1)} / 100 小时</span></div><div class="track"><i style="width:${hours}%"></i></div></div><div class="card-bottom">${p.retired?button('购买替代机','retirement','plane',`data-id="${p.id}"`,'primary'):''}${button('管理航线','planeRoutes','route',`data-id="${p.id}"`,'primary')}${button('检修','maintain','',`data-id="${p.id}" ${p.retired||p.delivery||p.maintenance?'disabled':''}`)}${button('调往基地','rebase','',`data-id="${p.id}"`)}${button(p.mode==='lease'?'退租':'出售','dispose','',`data-id="${p.id}" ${p.delivery?'disabled':''}`)}</div></div></article>`}).join('')||'<div class="empty">暂无符合条件的飞机。</div>'}</div>`;}
let catalogFiltersOpen=false;
function market(){const all=D.aircraft.filter(m=>(E.aircraftAvailable(state,m)||marketFilter==='虚拟飞机')&&(marketFilter==='全部'||m.type===marketFilter||marketFilter==='仅二手'&&m.usedOnly||marketFilter==='虚拟飞机'&&m.fictional||marketFilter==='超远程'&&m.range>=17500)&&(makerFilter==='全部制造商'||m.maker===makerFilter)&&(purchaseChannel!=='全新 / 租赁'||!m.usedOnly)).sort((a,b)=>marketFilter==='虚拟飞机'?a.releaseYear-b.releaseYear:0),rows=pageItems(all,'market','cards');return `${head('AIRCRAFT COLLECTION','选择下一架，飞向下一站。',`${D.aircraft.filter(m=>E.aircraftAvailable(state,m)).length} 款已上市 · 实际购置另计公司服务配置费`)}<details class="catalog-filters" id="catalog-filters" ${catalogFiltersOpen?'open':''}><summary>筛选机型 <span>${D.makers[makerFilter]?.name||makerFilter} · ${marketFilter}</span></summary><div class="catalog-controls"><label>制造商<select id="maker-filter" aria-label="按制造商筛选">${['全部制造商',...Object.keys(D.makers)].map(x=>`<option value="${x}" ${makerFilter===x?'selected':''}>${D.makers[x]?.name||x}</option>`).join('')}</select></label><label>机型类别<select id="category-filter" aria-label="按机型类别筛选">${['全部','支线客机','窄体客机','宽体客机','超远程','虚拟飞机','仅二手'].map(x=>`<option ${marketFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><label>采购渠道<select id="channel-filter" aria-label="按采购渠道筛选">${['全部货源','全新 / 租赁','二手飞机'].map(x=>`<option ${purchaseChannel===x?'selected':''}>${x}</option>`).join('')}</select></label></div></details>${pager('market')}<div class="page-grid catalog-grid">${rows.map(m=>`<article class="aircraft-card"><div class="plane-render">${planeSVG(m)}</div><div class="card-body"><div class="card-title"><span class="tag ${m.fictional?'amber':''}">${m.fictional?'虚拟飞机':m.usedOnly?'仅二手':m.type}</span><small>${E.cabinRules(m).first?'支持头等舱':'经济 / 商务舱'}</small></div><div class="specs"><div><small>默认座位</small>${m.seats} 席</div><div><small>参考航程</small>${m.range.toLocaleString()} km</div><div><small>燃油 / 小时</small>${m.fuel} 吨</div></div><div class="market-price"><small>${m.usedOnly||purchaseChannel==='二手飞机'?'二手报价起':'全新购置'}</small><strong>${money(m.usedOnly||purchaseChannel==='二手飞机'?Math.min(...E.usedOffers(m).map(o=>o.price)):m.price)}</strong></div>${button(E.aircraftAvailable(state,m)?'查看购置方案':`${m.releaseYear} 年开放`,'modelDetail','arrow',`data-model="${m.id}" ${E.aircraftAvailable(state,m)?'':'disabled'}`,'primary catalog-open')}</div></article>`).join('')||'<div class="panel empty">没有符合条件的机型，请更换筛选。</div>'}</div><p class="catalog-footnote">A380、747-8 仅二手 · 虚拟机按游戏年份上市，筛选「虚拟飞机」可查看计划 · 运营航程保留 6% 余量</p>`;}
function modelDetail(id){const m=E.model(id);if(!E.aircraftAvailable(state,m)){toast(`${E.modelName(m)} 将于 ${m.releaseYear} 年开放（游戏设定）`);return;}const usedOnly=m.usedOnly||purchaseChannel==='二手飞机';showModal(esc(E.modelName(m)),`${planeSVG(m)}<p class="model-detail-copy">${esc(m.description||'为不同市场配置自己的客舱，并按航程、需求和成本安排航线。')}${m.fictional?' 本机性能、价格与供货均为虚拟设定。':''}</p><div class="quote"><div><small>默认 / 最大座位</small>${m.seats} / ${E.cabinRules(m).max}</div><div><small>机型基础舒适度</small>${m.comfort}/100</div><div><small>运营航程上限</small>${Math.floor(m.range*.94).toLocaleString()} km</div><div><small>公司服务配置</small>${money(E.serviceFitout(state,m))}</div></div><div class="purchase-options">${usedOnly?'':`${button('全新购买 · '+money(m.price),'acquire','',`data-model="${id}" data-mode="buy"`,'primary')}${button('租赁押金 · '+money(m.deposit),'acquire','',`data-model="${id}" data-mode="lease"`)}<p>全新 6 周交付；租赁 2 周交付，每周租金 ${money(m.lease)}。</p>`}${button('查看二手报价','usedOffers','',`data-model="${id}"`)}</div><div class="form-actions">${button('返回机型库','closeModal')}</div>`,'比较购置方式 · 再确认资金支出');}

function usedMarket(id){const m=E.model(id);showModal(`${E.modelName(m)} · 二手机报价`,`${E.usedOffers(m).map(o=>`<section class="used-offer"><div class="card-title"><h3>${o.age/52} 年机龄</h3><span class="tag ${o.condition<80?'amber':''}">维护状态 ${o.condition}%</span></div><div class="quote"><div><small>购买价</small>${money(o.price)}</div><div><small>交付等待</small>1 周</div><div><small>机龄维护系数</small>×${E.ageFactor(o).toFixed(2)}</div></div><p>购入后拥有飞机产权。机龄越高，日常维护费用、检修费用和状态损耗越高；检修可恢复状态，不能清除机龄。</p>${button('查看购入方案','acquire','',`data-model="${id}" data-mode="used" data-offer="${o.key}"`,'primary')}</section>`).join('')}`,'机龄、维护状态及报价为模拟市场设定，不代表真实出售中的飞机。');}

const SERVICE=[['cabin','seat','客舱体验','升级座椅、客舱舒适度与机上连接。每级增加需求，旅客服务成本同步提高。'],['meal','meal','机上餐饮','从标准餐食到本地特色与精品餐饮，每级增加单客餐饮成本。'],['staff','people','乘务与地面服务','培训一线团队，改善沟通、响应和运行体验，持续提升口碑。'],['lounge','star','贵宾与会员服务','接入合作贵宾室和常旅客权益，按机队规模支付接入与会员服务配置费。']];
function delayPolicyModal(){const p=E.disruptionPolicy(state);showModal('延误保障策略',`<form id="delay-policy-form"><p>天气与航路管制按周随机影响部分航线。延误只影响本周，不再逐班连锁推演。</p><label class="field">严重延误时优先处理方式<select name="mode">${Object.entries(E.DELAY_POLICIES).map(([key,label])=>`<option value="${key}" ${p.mode===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field" style="margin-top:14px">每周自动改签预算上限<select name="budget">${[.5,1,3].map(n=>`<option value="${n}" ${p.budget===n?'selected':''}>${money(n)}</option>`).join('')}</select></label><p class="advisor-detail">延误超过 3 小时尝试保障。优先改签：按同航路班次密度与剩余运力估算自家改签，再按合作运力比例补充；运力或预算不足时，继续照顾旅客，部分旅客会退票。优先退款：严重延误旅客直接退还票款及辅营费用。</p><p class="advisor-detail">游戏补偿：延误超过 3 小时每人 250 元，6 小时起 500 元；2 小时起餐饮 80 元，6 小时起餐宿合计 480 元。自家改签服务成本每人 80 元；合作航司按原订单收入的 115% 加 60 元计费。改签预算还受当前现金限制，补偿与餐宿另计。</p><p class="muted">以上为游戏服务标准，不代表现实航司、法律赔偿规则或实时天气。合作运力为模拟报价，不保证存在空位。保存后持续自动执行，无需逐次确认，也不会因延误中断连续模拟。选择策略本身不扣费，实际发生后记入周报。</p><div class="form-actions">${button('取消','closeModal')}<button type="submit" class="btn primary">保存保障策略</button></div></form>`,'旅客体验 · 在成本与恢复出行之间作出选择');}
function delayPanel(page=0){const d=state.lastReport?.disruption;if(d?.simplified){simpleDelayPanel(d,page);return;}if(!d){toast('下一次周结算后可查看运行保障记录。');return;}const legs=d.legs.filter(l=>l.delay>=15),pages=Math.ceil(legs.length/4)+1;page=Math.max(0,Math.min(page,pages-1));let body='';if(page===0){body=`<p>${d.incidents.length?d.incidents.map(e=>esc(e.title)).join('；'):legs.length?'上周延误继续影响本周航班':'本周没有影响运营的天气或航路管制。'}</p><div class="quote"><div><small>延误 / 连锁航段</small>${d.delayedLegs} / ${d.propagatedLegs}</div><div><small>航段准点率</small>${d.onTime.toFixed(1)}%</div><div><small>受影响旅客</small>${d.affectedPax} 人</div><div><small>保障后满意度</small>${d.affectedPax?d.satisfaction.toFixed(1)+'/100':'—'}</div></div><p>本周策略：${esc(E.DELAY_POLICIES[d.policy])}。自家改签 ${d.rebookedOwn} 人，合作航司改签 ${d.rebookedPartner} 人，退款 ${d.refundedPax} 人；口碑影响 ${d.repDelta.toFixed(2)}。</p><div class="report-lines">${[['退票收入减少',d.refunds],['旅客现金补偿',d.compensation],['餐饮与住宿',d.care],['同航路改签支出',d.rebooking],['运行恢复额外开支',d.operations]].map(([label,n])=>`<div><span>${label}</span><span>−${money(n)}</span></div>`).join('')}<div class="total"><span>本周利润影响</span><strong>−${money(d.loss)}</strong></div></div><p class="muted">改签优先选择实际到达最早的同起讫机场航班，比较自家与合作航司空位及预算。改签后的到达晚点、赔付和食宿共同影响满意度；可靠性按近期表现逐周累积。合作航司运力为游戏模拟；补偿不能完全抵消等待带来的不满。周界后未消化的飞机延误会延续到下周。</p>`;}else body=legs.slice((page-1)*4,page*4).map(l=>`<article class="delay-leg"><span class="tag">${l.propagated?'前序晚到 · 连锁延误':'天气 / 航路影响'}</span><h3>${l.from} → ${l.to} · B-YS${String(l.plane).padStart(3,'0')}</h3><p>计划起飞 ${delayClock(l,l.plannedDep,l.from)} → 实际 ${delayClock(l,l.actualDep,l.from)}</p><p>计划到达 ${delayClock(l,l.plannedArr,l.to)} → 实际 ${delayClock(l,l.actualArr,l.to)}</p><strong class="negative">晚到 ${Math.round(l.delay)} 分钟</strong></article>`).join('');showModal(`第 ${d.week} 周 · 延误与旅客保障`,`<div class="advisor-pager"><span>${page===0?'保障与收支汇总':`航段明细 · ${page} / ${pages-1}`}</span></div>${body}<div class="form-actions">${button(page===0?'关闭':'上一页',page===0?'closeModal':'delayReport','','data-page="'+(page-1)+'"')}${button('调整保障策略','delayPolicy')}${page<pages-1?button('查看'+(page===0?'延误航段':'下一页'),'delayReport','arrow','data-page="'+(page+1)+'"','primary'):''}</div>`,'按实际航班传递延误 · 费用已计入本周结算');}
function delayClock(l,minute,airport){const c=E.localClock({...state,date:state.lastReport.date},l.base||state.base,minute,airport);return `${c.date} ${c.time}`;}
function service(){return `${head('PASSENGER EXPERIENCE','让旅客，期待下一次与你相遇。','按实际机队座位规模收费；新购、二手和租赁飞机另付配置费以匹配公司标准。',button('延误保障策略','delayPolicy','shield')+button('上周延误记录','delayReport','clock'))}${stats([['旅客口碑',state.rep.toFixed(1),'/ 100','实际乘机体验累积；延误、误机及停航扣分','star',true],['服务投入',E.services(state),'/ 20 级','四个维度，每项最高 5 级','seat'],['运行可靠性',state.reliable.toFixed(1),'%','受维护、停航与实际延误影响','shield'],['累计承运',state.totalPassengers.toLocaleString(),'人次','每一次旅程，都在积累信任','people']])}<div class="page-grid service-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${SERVICE.map(([key,icon,title,desc])=>`<article class="panel service-card"><div class="service-icon">${ic(icon,22)}</div><div class="card-title"><h3>${title}</h3><small>LEVEL ${state.service[key]} / 5</small></div><p>${desc}</p><div class="service-level">${[1,2,3,4,5].map(n=>`<i class="${state.service[key]>=n?'on':''}"></i>`).join('')}</div>${button(state.service[key]<5?`升级服务 · ${money(E.serviceUpgradeCost(state,key))}`:'已达最高等级','serviceUpgrade','plus',`data-key="${key}" ${state.service[key]===5?'disabled':''}`,'primary')}</article>`).join('')}</div><p class="notice" style="margin-top:20px">本次升级覆盖 ${state.fleet.length} 架飞机、${state.fleet.reduce((n,p)=>n+E.cabinStats(E.model(p.model),E.cabinOf(p)).total,0)} 个座位（含待交付订单）。每座每级一次性投入：客舱 2,000 元，餐饮设备 450 元，人员培训 300 元，贵宾与会员接入 200 元。以 180 座飞机为例，四项从 0 升到 5 共 265.5 万；从默认标准升满约 216 万。餐食、人员等持续费用另在每周结算。价格是游戏成本设定。</p>`;}
function calendarUpcoming(){let y=+state.date.slice(0,4);let lunar={2026:'02-17',2027:'02-06',2028:'01-26',2029:'02-13',2030:'02-03',2031:'01-23',2032:'02-11',2033:'01-31',2034:'02-19',2035:'02-08'};let spring=lunar[y]?new Date(Date.parse(y+'-'+lunar[y])-14*86400000).toISOString().slice(0,10):null;let c=[...(spring?[{date:spring,title:'春节春运',desc:'探亲与返乡需求上升，提前安排运力与检修。',when: y+' 年春节前后 · 游戏近似窗口'}]:[]),{date:`${y}-04-27`,title:'五一出游季',desc:'国内及亚洲周边旅游需求上升。',when:'4 月下旬 — 5 月上旬'},{date:`${y}-07-01`,title:'暑期旅行旺季',desc:'全球家庭旅行与学生出行增加。',when:'7 月 — 8 月'},{date:`${y}-09-28`,title:'国庆黄金周',desc:'提前配置热门城市与度假航线运力。',when:'9 月下旬 — 10 月上旬'},{date:`${y}-12-15`,title:'圣诞与新年假期',desc:'欧美与大洋洲跨境探亲需求旺盛。',when:'12 月中下旬'},{date:'2026-06-11',title:'美加墨世界杯',desc:'北美赛事客流上升，关注远程运力准备。',when:'2026.06.11 — 07.19'},{date:'2028-07-14',title:'洛杉矶奥运会',desc:'洛杉矶与美国西海岸将迎来赛事客流。',when:'2028.07.14 — 07.30'},{date:'2030-06-01',title:'2030 世界杯赛事季',desc:'游戏近似赛事窗口，非最终官方赛程。',when:'2030 年 6—7 月 · 近似'},{date:'2032-07-23',title:'布里斯班奥运会',desc:'澳大利亚市场迎来重要赛事窗口。',when:'2032.07.23 — 08.08'}];return c.filter(e=>e.date>state.date).sort((a,b)=>a.date.localeCompare(b.date));}
function events(){const active=E.activeEvents(state);return `${head('WORLD INTELLIGENCE','世界的变化，也是航线的机会。','节庆、赛事与国际情景将改变需求、油价及航路可用性。')}${state.pending?`<section class="section-intro" style="background:#f6f0df"><div><small>${esc(state.pending.tag)}</small><h2 style="margin-top:5px">${esc(state.pending.title)}</h2><p>董事会需要你的决定。结算前必须完成处理。</p></div>${button('查看并决策','story','arrow','','primary')}</section>`:''}<div class="notice">外交、冲突、油价与竞争故事均为虚构经营情景；节庆窗口为游戏近似，赛事按所列年份触发。游戏不提供实时新闻或现实战争预测。</div><h2 style="margin-bottom:15px">本周正在影响市场</h2><div class="page-grid">${active.map(e=>`<article class="panel event-card"><span class="tag ${e.calendar?'':'amber'}">${e.calendar?'季节与赛历':'模拟情景'}</span><h3>${esc(e.title)}</h3><p>${esc(e.desc)}</p><div class="impact">${e.closed?'相关航线暂停运营':`相关需求 ×${(e.demand??1).toFixed(2)} · 燃油价格 ×${(e.fuel||1).toFixed(2)}`}${e.calendar?'':` · 持续至第 ${e.until} 周`}</div></article>`).join('')||'<div class="panel empty">本周市场平稳，可专注航线优化与机队维护。</div>'}</div><h2 style="margin:26px 0 15px">提前看下一站</h2><div class="page-grid">${calendarUpcoming().map(e=>`<article class="panel event-card"><small class="mono">${e.when}</small><h3>${e.title}</h3><p>${e.desc}</p></article>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>公司经营纪事</h2><small>最近 ${Math.min(20,state.log.length)} 条</small></div><div class="timeline">${state.log.slice(0,20).map(l=>`<div class="timeline-row"><span>W${String(l.week).padStart(2,'0')}</span><div class="${l.type==='warn'?'negative':''}">${esc(l.text)}</div></div>`).join('')}</div></section>`;}
function finance(){const r=state.lastReport,history=state.history.slice(-12),max=Math.max(1,...history.flatMap(x=>[x.revenue,x.cost]));return `${head('FINANCIAL HEALTH','让每一次增长，都有底气。','关注现金流与持续盈利，留出面对淡季和意外的余量。',button('融资方案','loan','wallet')+button('经营记录 / 更多模拟','batchPanel','clock'))}${stats([['可用现金',money(state.cash),'人民币','实时现金余额','wallet'],['上周营业收入',r?money(r.revenue):'—','人民币',r?`${r.pax.toLocaleString()} 人次 · ${r.flights} 个单程航班`:'完成一周经营后生成','chart'],['上周净利润',r?money(r.profit,true):'—','人民币','扣除租金、薪酬、总部费用与利息','arrowup',r&&r.profit>0],['融资负债',money(E.totalDebt(state)),'人民币','银行授信 + 飞机抵押贷款','building']])}<div class="two-col"><section class="panel padded"><div class="card-title"><h2>收入与成本趋势</h2><small>最近 12 周</small></div>${history.length?`<div class="chart">${history.map(h=>`<div class="chart-group" title="第 ${h.week} 周：收入 ${money(h.revenue)}，成本 ${money(h.cost)}"><i style="height:${h.revenue/max*100}%"></i><i class="cost" style="height:${h.cost/max*100}%"></i><span>W${h.week}</span></div>`).join('')}</div><div class="map-legend" style="justify-content:center"><span><i class="map-key"></i>营业收入</span><span><i class="map-key dim"></i>全部成本</span></div>`:'<div class="empty">完成第一周后，经营曲线将在这里展开。</div>'}</section><section class="panel padded"><h2 style="margin-bottom:20px">上周收支明细</h2>${r?reportLines(r):'<div class="empty">尚未结算首周。</div>'}</section></div><section class="panel padded" style="margin-top:20px"><h2>融资与现金管理</h2><div class="settings-row"><div><strong>银行授信</strong><p>基础授信 1.5 亿元 + 未抵押自有飞机估值的 45%，贷款无固定期限，可提前还款。</p></div>${button('申请贷款','loan','','','primary')}</div><div class="settings-row"><div><strong>提前偿还负债</strong><p>优先保留覆盖机队租金和运营成本的现金。</p></div>${button('偿还贷款','repay','',`${state.debt<=0?'disabled':''}`)}</div><div class="settings-row"><div><strong>航油套期保值</strong><p>支付 200 万元，未来 12 周按基础油价结算；不会抵消绕飞带来的耗油增加。</p></div>${button(state.fuelHedge>=state.week?'套保生效中':'锁定航油价格','hedge','',`${state.fuelHedge>=state.week?'disabled':''}`)}</div></section>${financingPanels()}`;}
function reportLines(r){return `<div class="report-lines"><div><span class="muted">票款与辅营收入</span><span>${money((r.flightRevenue??r.revenue)+(r.disruption?.refunds||0))}</span></div>${r.hangarRevenue?`<div><span class="muted">机库外部订单收入</span><span>${money(r.hangarRevenue)}</span></div>`:''}<div><span class="muted">燃油、机场、客舱及维护准备</span><span>−${money(r.variable-(r.hangarCost||0)-(r.maintenanceCost||0)-(r.disruption?.totalCost||0))}</span></div>${r.disruption?.loss?`${[['延误退票 · 收入冲减',r.disruption.refunds],['延误现金补偿',r.disruption.compensation],['延误餐饮与住宿',r.disruption.care],['同航路改签费用',r.disruption.rebooking],['运行恢复额外支出',r.disruption.operations]].filter(([,n])=>n).map(([label,n])=>`<div><span class="muted">${label}</span><span>−${money(n)}</span></div>`).join('')}`:''}<div><span class="muted">飞机租赁</span><span>−${money(r.leaseGross??r.lease)}</span></div>${r.leaseRentRefund?`<div><span class="muted">提前收回 · 未用租金返还</span><span>+${money(r.leaseRentRefund)}</span></div>`:''}<div><span class="muted">机组与运营薪酬</span><span>−${money(r.payroll)}</span></div><div><span class="muted">基地、总部与服务固定投入</span><span>−${money(r.overhead)}</span></div>${r.maintenanceCost?`<div><span class="muted">自动检修支出 · ${r.autoMaintenance.length} 架</span><span>−${money(r.maintenanceCost)}</span></div>`:''}${r.hangarCost?`<div><span class="muted">机库材料、人工与固定开支</span><span>−${money(r.hangarCost)}</span></div>`:''}<div><span class="muted">贷款利息</span><span>−${money(r.interest)}</span></div><div class="total"><span>本周净利润</span><span class="${r.profit>=0?'positive':'negative'}">${money(r.profit,true)}</span></div>${r.leaseDepositRefund?`<div><span>租赁押金返还（不计营业利润）</span><span>+${money(r.leaseDepositRefund)}</span></div>`:''}${r.principal?`<div><span>偿还抵押本金（不计入费用）</span><span>−${money(r.principal)}</span></div><div><span>经营现金净变动</span><strong>${money(r.cashFlow,true)}</strong></div>`:''}${r.pax&&r.cabinComfort?`<div><span>乘客实际客舱体验</span><span>${r.cabinComfort.toFixed(1)} / 100</span></div>`:''}</div>`;}
let trafficTab='airlines',trafficPage=0,trafficMine=false,trafficQuery='',contestKey='',contestPage=0,trafficSize=2;
function trafficPageSize(){return window.innerHeight<=500?1:layoutMode()==='wide'?4:2;}
function resizeTrafficPanel(){
 if(!$('.traffic-modal')||trafficSize===trafficPageSize())return;
 const input=$('#traffic-search-form input'),draft=input?.value,focused=document.activeElement===input;
 const size=trafficPageSize(),page=Math.floor(trafficPage*trafficSize/size);
 trafficPanel(trafficTab,page,size);
 const next=$('#traffic-search-form input');if(next&&draft!==undefined){next.value=draft;if(focused)next.focus();}
}
function trafficData(){return state.trafficReport||E.trafficSnapshot(state);}
function trafficPanel(tab=trafficTab,page=trafficPage,size=trafficPageSize()){
 trafficTab=tab;const data=trafficData(),mine=data.airlines.find(a=>a.player),all=(tab==='airlines'?data.airlines:tab==='airports'?data.airports.filter(a=>!trafficMine||a.playerHub):data.markets).filter(a=>!trafficQuery||JSON.stringify(tab==='markets'?[E.ap(a.from).city,E.ap(a.to).city,a.from,a.to]:[a.name,a.city,a.code,a.country]).toLowerCase().includes(trafficQuery.toLowerCase()));
 trafficSize=size;trafficPage=Math.max(0,Math.min(page,Math.ceil(all.length/size)-1));const rows=all.slice(trafficPage*size,(trafficPage+1)*size);
 const content=rows.map(a=>tab==='airlines'?`<article class="traffic-row ${a.player?'traffic-own':''}"><span class="rank-badge">${a.rank}</span><button class="airline-name airline-detail-link" data-action="airlineDetail" data-code="${a.code}"><strong>${esc(a.name)}</strong><small>${a.player?'你的航司':esc(E.ap(a.hub).city)} · ${a.fleet} 架</small></button><div><strong>${a.journeys.toLocaleString()}</strong><small>旅客行程 / 周</small></div></article>`:tab==='airports'?`<article class="traffic-row ${a.playerHub?'traffic-own':''}"><span class="rank-badge">${a.rank}</span><button class="airline-name airline-detail-link" data-action="trafficAirport" data-code="${a.code}"><strong>${esc(a.city)} · ${esc(a.name)}</strong><small>${a.code}${a.playerHub?' · 你的基地':''}</small></button><div><strong>${a.movements.toLocaleString()}</strong><small>进出港人次 / 周</small></div></article>`:`<article class="traffic-row"><div><strong>${esc(E.ap(a.from).city)} → ${esc(E.ap(a.to).city)}</strong><small>${a.via.length?'经 '+a.via.map(c=>esc(E.ap(c).city)).join(' / '):'本地直达市场'} · ${a.own.toLocaleString()} 行程</small></div><div><strong>${(a.share*100).toFixed(1)}%</strong><small>你的市场份额</small></div>${button('比较方案','trafficContest','','data-key="'+[a.from,a.to].sort().join('-')+'"')}</article>`).join('');
 showModal('全球客流与市场竞争',`<nav class="dossier-tabs traffic-tabs" aria-label="客流榜分区">${[['airlines','航司客流'],['airports','机场客流'],['markets','市场竞争']].map(([id,label])=>`<button class="btn ${tab===id?'primary':''}" data-action="trafficTab" data-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</nav><form id="traffic-search-form" class="traffic-search"><input name="query" value="${esc(trafficQuery)}" aria-label="搜索客流榜" placeholder="搜索名称、城市或代码"><button class="btn" type="submit">查找</button></form><p class="traffic-summary">${tab==='airlines'?`你排第 <strong>${mine.rank}</strong> / ${data.airlines.length} · ${mine.journeys.toLocaleString()} 次行程`:tab==='airports'?button(trafficMine?'显示全部机场':'查看我的基地','trafficMine'): '已实际销售的直达与中转市场；对手反应影响下周销量。'}</p><div class="traffic-list">${content||'<p class="empty">尚无运营客流，先开航并完成一次经营。</p>'}</div><p class="muted traffic-note">${tab==='airlines'?'联程旅客只计一次行程；品质综合榜保持独立。':tab==='airports'?'到达、出发各计一次；转机在枢纽计两次，不合并同城机场。':'份额按同一出发地—目的地统计，直飞和转机争夺同一批旅客。'}</p><div class="form-actions network-footer"><div class="network-pager">${button('上一页','trafficPage','','data-delta="-1" '+(trafficPage===0?'disabled':''))}<span>${trafficPage+1} / ${Math.max(1,Math.ceil(all.length/size))}</span>${button('下一页','trafficPage','','data-delta="1" '+((trafficPage+1)*size>=all.length?'disabled':''))}</div>${button('返回','closeModal')}</div>`,`第 ${data.week} 周 · ${data.settled?'已结算':'当前预计'} · 全球市场采用游戏模型，非实时行业统计`);$('.modal').classList.add('traffic-modal');
}
function trafficAirport(code){const data=trafficData(),a=data.airports.find(a=>a.code===code);showModal(`${esc(a.city)} · ${esc(a.name)} (${code})`,`<div class="quote network-metrics"><div><small>机场客流排名</small>#${a.rank}</div><div><small>周进出港人次</small>${a.movements.toLocaleString()}</div><div><small>你的进出港贡献</small>${a.own.toLocaleString()}</div><div><small>经你航司转机的行程</small>${a.transfers.toLocaleString()}</div></div><p>机场发展积累 ${(a.growth||0).toFixed(1)} 点 · 长期需求增幅 +${(((a.demandFactor||1)-1)*100).toFixed(1)}%。实际承运、基地扩建和城市合作逐步增加积累，赛事和节庆另带来短期变化。</p><p>你的贡献占机场客流 ${a.movements?(a.own/a.movements*100).toFixed(1):'0.0'}%。增长来自真正承运的直达和联程旅客，客流受实际承运、机场成长与当前剧情共同影响。</p><div class="form-actions">${button('返回机场榜','trafficTab','','data-tab="airports"')}${a.playerHub?button('查看枢纽分析','network'):''}</div>`,`第 ${data.week} 周 · ${data.settled?'结算记录':'预计客流'}`);}
function trafficContest(key=contestKey,page=0){contestKey=key;const data=trafficData(),m=data.markets.find(m=>[m.from,m.to].sort().join('-')===key);if(!m){trafficPanel('markets',0);return;}contestPage=Math.max(0,Math.min(page,m.rivals.length-1));const r=m.rivals[contestPage];showModal(`${esc(E.ap(m.from).city)} → ${esc(E.ap(m.to).city)}`,`<div class="quote network-metrics"><div><small>你的周旅客行程</small>${m.own.toLocaleString()}</div><div><small>市场份额</small>${(m.share*100).toFixed(1)}%</div></div>${r?`<h3>${esc(r.name)} · ${r.direct?'直飞方案':'经 '+esc(E.ap(r.hub).city)+' 中转'}</h3><p>每周约 ${r.freq} 班 · 票价指数 ${(r.price*100).toFixed(0)}% · ${r.response}</p><p>总耗时约 ${(r.duration/60).toFixed(1)} 小时${r.wait?'，含转机等待 '+r.wait+' 分钟':''}；航程为直线距离的 ${r.detour.toFixed(2)} 倍。</p>`:'<p>目前没有主要对手方案。</p>'}<p class="traffic-note">${m.via.length?'发挥顺路中转优势、缩短两段等待，避免为了低价绕远。':'提高班次便利度，并保持可靠性与旅客口碑。'}对手会随你的份额逐步反应；单纯扩机不能保证客源。</p><div class="form-actions network-footer"><div class="network-pager">${button('前一个','contestPage','','data-delta="-1" '+(!contestPage?'disabled':''))}<span>对手 ${r?contestPage+1:0} / ${m.rivals.length}</span>${button('后一个','contestPage','','data-delta="1" '+(contestPage+1>=m.rivals.length?'disabled':''))}</div><div class="network-buttons">${button('返回','trafficTab','','data-tab="markets"')}${button('调整相关航线','trafficRoutes','','data-key="'+key+'"','primary')}</div></div>`,`第 ${data.week} 周市场 · 对手班次与报价采用游戏模型`);}
function trafficRoutes(key){const m=trafficData().markets.find(m=>[m.from,m.to].sort().join('-')===key);if(!m)return;const routes=state.routes.filter(r=>m.routes.includes(r.id));showModal('调整竞争市场的航线',routes.map(r=>`<p>${esc(E.ap(r.from).city)} → ${esc(E.ap(r.to).city)} · 每周 ${r.freq} 次往返 ${button('调整','editRoute','','data-id="'+r.id+'"')}</p>`).join('')+`<div class="form-actions">${button('返回市场','trafficTab','','data-tab="markets"')}${button('查看航班排班','navigate','','data-target="schedule"')}</div>`);}

function ranking(){return `${head('GLOBAL AIRLINE INDEX','世界一流，由你定义。',`全球 ${D.airlines.length} 家客运航司，其中 ${D.airlines.filter(a=>!a.country.startsWith('中国')).length} 家海外航司；分数与名次为游戏模拟。`,button('全球客流与竞争','traffic','people'))}${stats([['你的综合排名','#'+(E.rankings(state).findIndex(x=>x.player)+1),'/ '+(D.airlines.length+1),'与国内外主要航司同场竞技','award'],['综合得分',E.score(state),'/ 100','规模、服务、口碑、可靠性与盈利','star'],['航司资料库',D.airlines.length,'家','国内外客运航空公司','globe'],['连续盈利',state.profitStreak,'周','持续盈利为综合评分提供加分','chart']])}<div class="filters"><div class="search"><input id="rank-search" placeholder="搜索航司、国家或地区…" value="${esc(rankQuery)}" aria-label="搜索航司"></div>${['全部','中国内地','港澳台','国际','低成本'].map(x=>`<button class="filter-btn ${rankFilter===x?'active':''}" data-action="rankFilter" data-filter="${x}">${x}</button>`).join('')}</div><section class="panel"><div id="ranking-table">${rankingTable()}</div></section><p class="info-inline" style="margin-top:14px">评分权重：口碑 27% + 机队 18% + 覆盖城市 18% + 服务 20% + 可靠性 12% + 连续盈利 5%。机队 100 架、覆盖 100 座城市分别满分，超过不再加分；同城多机场去重，重复开线和加密班次不直接增加排名分。点击航司查看分项与现实参考。</p>`;}
function rankingTable(){const rows=E.rankings(state).map((r,i)=>({...r,rank:i+1})).filter(r=>(rankFilter==='全部'||rankFilter==='中国内地'&&r.country==='中国'||rankFilter==='港澳台'&&['中国香港','中国澳门','中国台湾'].includes(r.country)||rankFilter==='国际'&&!r.country.startsWith('中国')||rankFilter==='低成本'&&r.style==='低成本'||rankFilter==='货运'&&r.style==='货运')&&(`${r.name}${r.country}${r.code}`).toLowerCase().includes(rankQuery.toLowerCase()));const visible=pageItems(rows,'ranking');return `${pager('ranking')}<div class="table-scroll ranking-scroll"><table class="ranking-grid"><thead><tr><th>全球排名</th><th>航空公司</th><th>国家 / 地区</th><th>经营模式</th><th>机队 / 覆盖城市</th><th>综合得分</th><th>竞争动态</th></tr></thead><tbody>${visible.map(r=>`<tr class="${r.player?'leader-row-player':''}"><td><span class="rank-badge ${r.rank<=3?'gold':''}">${r.rank}</span></td><td><button class="airline-name airline-detail-link" data-action="airlineDetail" data-code="${r.player?'player':r.code}" aria-label="查看${esc(r.name)}详情"><strong>${esc(r.name)}</strong></button></td><td>${r.country}</td><td><span class="tag grey">${r.style}</span></td><td class="airline-size">${r.fleet} 架 / ${r.coverage} 城</td><td class="rank-score">${r.score.toFixed(1)}</td><td><span class="${r.player?'positive':'muted'}">${r.player?'持续成长':r.score>=90?'全球标杆':r.score>=80?'国际竞争力':'区域发展'}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有找到符合条件的航司。</td></tr>'}</tbody></table></div>`;}
function fleetReferenceInfo(r){const f=r.fleetReference;if(!f)return '';return `<details class="fleet-reference"><summary>机队资料 · ${esc(f.asOf)}</summary><p>${esc(f.scope)}</p><p>起始机队 ${f.mix.reduce((n,m)=>n+m.count,0)} 架，经营至今新增 ${r.fleetGrowth} 架。</p><a href="${esc(f.source)}" target="_blank" rel="noopener noreferrer">${f.basis==='snapshot'?'机队数量参考':'机型资料参考'} ↗</a></details>`;}

function airlineScores(r,tab='scores'){const labels={rep:'旅客口碑',fleet:'机队规模',coverage:'城市覆盖',service:'旅客服务',reliable:'运行可靠性',profit:'持续盈利'},raw={rep:`${r.components.rep.toFixed(1)} / 100`,fleet:`${r.fleet} 架 · 100 架封顶`,coverage:`${r.coverageCities} 城 · 100 城封顶`,service:`${r.components.service.toFixed(1)} / 100`,reliable:`${r.components.reliable.toFixed(1)}%`,profit:r.player?`${state.profitStreak} / 26 周连续盈利`:'成熟航司盈利基准'};return `<div class="score-summary"><strong>${r.score.toFixed(1)}<small> / 100</small></strong><span>游戏综合排名 #${r.rank}</span></div><div class="score-breakdown">${(tab==='scale'?['fleet','coverage','profit']:['rep','service','reliable']).map(key=>[key,E.SCORE_WEIGHTS[key]]).map(([key,weight])=>`<div class="score-item"><div><strong>${labels[key]}</strong><small>${raw[key]}</small></div><div><strong>${r.components[key].toFixed(1)} <small>分</small></strong><small>权重 ${weight}% · 贡献 ${r.contributions[key].toFixed(2)}</small></div><div class="track"><i style="width:${r.components[key]}%"></i></div></div>`).join('')}</div><p class="score-rule">规模达标后，增购飞机或新增城市不再拉高规模分。综合分为各项加权之和，最后四舍五入至一位小数。</p><details class="score-reference"><summary>现实参考与计分口径</summary><p>${r.reference?`<a href="${r.reference.source}" target="_blank" rel="noopener noreferrer">Skytrax ${r.reference.year}：第 ${r.reference.rank} 名 ↗</a>。以旅客评价排名校准本航司的初始口碑与服务，未将现实名次直接当作游戏名次。`:r.player?'你的分数来自当前经营存档。服务升级不立即加分；服务分随每周真实乘机体验逐步积累，延误和取消会拖累口碑与可靠性。':'本航司沿用既有游戏评级，本轮没有引用其现实榜单名次。'}</p><p>${r.player?'覆盖按有在役执飞机的在营航线停靠城市去重，含基地及经停；同城不同机场计一城，待交付飞机不计规模。':'覆盖城市沿用现有航网规模估算；可靠性与盈利为游戏设定，子项并非评级机构发布的分数。'} 现实参考为 2026 年资料快照，不随游戏日期伪造年度评奖。</p></details>`;}
function airlineDetail(key,tab='scores'){const r=E.airlineProfile(state,key),player=r.player;showModal(esc(r.name),`<div class="airline-dossier"><nav class="dossier-tabs" aria-label="航司档案分区">${[['scores','品质得分'],['scale','规模得分'],['profile','航司资料']].map(([id,label])=>`<button class="btn ${tab===id?'primary':''}" data-action="airlineDetailTab" data-code="${key}" data-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</nav>${tab!=='profile'?airlineScores(r,tab):`<div class="dossier-top"><div><span class="eyebrow">AIRLINE PROFILE · W${state.week}</span><h3>${r.country} · ${r.style}</h3><p>全球综合排名 #${r.rank} · ${r.score.toFixed(1)} 分</p></div></div><div class="dossier-stats">${[['在役飞机',r.fleet,'架'],['运营航线',r.routes,'条'],['覆盖城市',r.coverageCities,'座'],['待交付订单',r.orders,'架']].map(([l,v,u])=>`<div><small>${l}</small><strong>${v.toLocaleString()} <em>${u}</em></strong></div>`).join('')}</div><div class="dossier-columns"><section><h3>${player?'当前机队构成':'机队构成'}</h3>${player?'':fleetReferenceInfo(r)}${r.mix.map(m=>`<div class="fleet-mix"><span>${esc(E.model(m.id)?E.modelName(m.id):m.id)}</span><strong>${m.count} 架</strong><div class="track"><i style="width:${r.fleet?m.count/r.fleet*100:0}%"></i></div></div>`).join('')||'<p>暂无已交付飞机。</p>'}<div class="report-lines"><div><span>服务水平</span><strong>${r.service.toFixed(1)} / 5</strong></div><div><span>运行可靠性</span><strong>${r.reliability.toFixed(1)}%</strong></div></div></section><section><h3>总部与运营中心</h3><dl><dt>${player?'公司总部':r.facts?'总部':'运营中心'}</dt><dd>${esc(player?r.headquarters:r.facts?.headquarters||r.headquarters)}</dd><dt>${player?'运营基地':'主枢纽'}</dt><dd>${r.hubs.map(c=>`${E.ap(c).city} · ${E.ap(c).name} (${c})`).join('<br>')}</dd><dt>经营定位</dt><dd>${r.style==='货运'?'货运参考航司，不参与玩家客运分流':r.style==='低成本'?'高密度客舱、价格竞争与较高飞机利用率':r.style==='支线'?'连接中小城市与区域枢纽':'枢纽网络、商务需求与旅客服务'}</dd></dl>${r.facts?`<a class="info-inline" href="${r.facts.source}" target="_blank" rel="noopener noreferrer">总部资料来源 ↗</a>`:''}</section></div>${player?'':`<section class="dossier-competition"><h3>与你的竞争关系 · ${r.overlap.length} 条航线</h3>${r.overlap.length?`<p>以下市场已在你的需求预估中计入这家航司的竞争影响。</p>${r.overlap.map(x=>button(`${x.from} → ${x.to} · 查看经营`,'editRoute','',`data-id="${x.id}"`,'tiny')).join('')}`:`<p>${r.style==='货运'?'货运航司不分流客运需求。':'当前没有在你的在营航线上直接竞争。'}</p>`}</section>`}<p class="dossier-note">${player?'以上数据读取你的当前存档，停飞航线不计入运营航线，待交付飞机单列。':'机队规模随经营发展变化；A380、747 等停产机型保留存量，不随季度扩张自动增加。'}</p>`}<div class="form-actions">${button('返回排行榜','navigate','','data-target="ranking"')}${player?button('管理我的机队','navigate','','data-target="fleet"','primary'):button('查看市场洞察','navigate','','data-target="insights"','primary')}</div></div>`,player?'你的公司 · 即时经营档案':'航司档案',true);}
function company(){const missions=[['首航成功','完成第一个经营周',state.week>1,`${Math.min(1,state.week-1)} / 1`],['区域新势力','拥有 5 架已交付飞机',state.fleet.filter(p=>!p.retired&&!p.delivery).length>=5,`${state.fleet.filter(p=>!p.retired&&!p.delivery).length} / 5`],['国际化起点','获得国际及地区航线资质',state.license,state.license?'已完成':'待申请'],['十万份信任','累计承运 100,000 人次',state.totalPassengers>=1e5,`${state.totalPassengers.toLocaleString()} / 100,000`],['卓越服务','四项服务全部达到 5 级',E.services(state)===20,`${E.services(state)} / 20`],['世界最佳航司','登顶全球综合排名第 1',state.won,`当前第 ${E.rankings(state).findIndex(x=>x.player)+1} 名`]];return `${head('COMPANY DEVELOPMENT','把一家航司，做成一个时代的名字。','发展基地、解锁国际网络，在一座座里程碑中成长。')}<div class="two-col"><section><div class="panel padded" style="margin-bottom:18px"><h2>国际及地区航线资质</h2><p class="subtitle" style="margin:10px 0 17px">满足口碑 60、已交付飞机 3 架、10 条不同的在营国内航线后，可支付 800 万申请。审批耗时 4 周。</p><div class="progress-row"><div><span>品牌口碑</span><span>${state.rep.toFixed(1)} / 60</span></div><div class="track"><i style="width:${Math.min(100,state.rep/60*100)}%"></i></div></div><div class="progress-row"><div><span>已交付飞机</span><span>${state.fleet.filter(p=>!p.retired&&!p.delivery).length} / 3</span></div></div><p>在营国内航线：${E.domesticRoutes(state)} / 10 条</p>${button(state.license?'已获得国际资质':state.licenseDue?`审批中 · 还有 ${state.licenseDue} 周`:'申请国际资质','license','globe',`${state.license||state.licenseDue?'disabled':''}`,'primary')}</div><section class="panel padded"><div class="card-title"><h2>运营基地</h2>${button('增加基地','hub','plus','','tiny')}</div><p class="notice">${E.ap(state.base).city}门户影响力 ${E.hubInfluence(state).value} / 100 · 国内需求指数第 ${E.hubInfluence(state).rank} 位。城市合作可持续提升基地需求。</p>${state.hubs.map(h=>`<div class="settings-row"><div><strong>${E.ap(h.code).city} ${h.code}</strong><p>等级 ${h.level} · 每周 ${h.level*180} 个单程时刻</p></div>${button('扩建 '+money(h.level*18),'expandHub','',`data-code="${h.code}"`,'tiny')}</div>`).join('')}<div class="settings-row"><div><strong>品牌推广计划</strong><p>投入 300 万，未来四周所有运营航线的客流提升 12%，受座位上限约束。</p></div>${button(state.marketing>=state.week?'推广中':'开始推广','marketing','',`${state.marketing>=state.week?'disabled':''}`,'tiny')}</div></section></section><section><h2 style="margin-bottom:15px">成长里程碑</h2>${missions.map(([title,desc,done,progress])=>`<div class="achievement ${done?'done':''}"><span class="medal">${ic(done?'check':'flag',18)}</span><div><h3>${title}</h3><p>${desc}</p><div class="mission-progress">${done?'已达成 · ':''}${progress}</div></div></div>`).join('')}</section></div>`;}
function settings(){const backups=saveStore.backups();return `${head('YOUR AIRLINE, SAFELY SAVED','每一程，都值得保留。','改版继续原进度；自动保留上次保存和改版前备份。跨浏览器、跨设备或离线/线上迁移请导出再导入。')}<section class="panel padded"><div class="settings-row"><div><h3>当前航司</h3><p>${esc(state.name)} · ${dateText()} · 第 ${state.week} 周</p></div><span class="tag">${saveError?'存储不可用':'自动保存已开启'}</span></div><div class="settings-row"><div><h3>导出经营存档</h3><p>下载当前机队、航线、资金与完整经营进度。</p></div>${button('导出存档','export','download','','primary')}</div><div class="settings-row"><div><h3>导入经营存档</h3><p>旧格式自动补齐新字段；校验通过后才替换，当前进度先备份。</p></div>${button('选择存档','import','book')}</div>${backups.map(b=>`<div class="settings-row"><div><h3>${b.label}</h3><p>${esc(b.name)} · 第 ${b.week} 周 · ${dateText(b.date)}</p></div>${button('查看恢复','restoreSave','',`data-backup="${b.id}"`)}</div>`).join('')}<div class="settings-row"><div><h3>创立另一家航空公司</h3><p>选择新的中国基地机场与航司名称，从初始资金重新出发。</p></div>${button('重新开始','newGame','plus','','danger')}</div><div class="settings-row"><div><h3>经营指南与数值规则</h3><p>了解排班、航线贡献、现金与服务评分。</p></div>${button('查看指南','guide','info')}</div></section>`;}
function sources(){return `${head('REFERENCE & SIMULATION','真实的航空世界，可玩的经营规则。','透明区分现实资料、游戏参数和虚构事件。')}<section class="panel padded"><h2>收录范围</h2><p class="subtitle" style="line-height:2;margin:12px 0 22px">首版收录 ${D.airports.length} 座机场、${D.aircraft.length} 款现代飞机及 ${D.airlines.length} 家主要客运航司。国内部分收录民航局名录所列 65 家运输航空公司（含货运及集团子公司），海外部分为知名品牌精选，不声称覆盖世界全部航司。货运航司仅作资料与综合榜参照，不分流客运需求；玩家当前经营客运业务。航司合并、品牌运营与资质状态可能变化。飞机卡片采用制造商标志与标准名称；总览保留 A350 实拍。虚拟飞机均明确标注；品牌仅用于机型识别，不代表官方合作。</p><h2>公开参考入口</h2><p class="subtitle" style="margin:8px 0 14px">新增机场代码与坐标已对照 OurAirports 公有领域数据；已核对民航局运输航空公司名录、空客 A320neo 与波音 787 官方产品页，以及 FIFA 2026 赛事日期。其他机型采用公开常见规格的游戏参考值，仍需逐型号复核；部分赛历使用已标注的近似窗口。资料核对日：2026 年 10 月 24 日。</p><div class="source-list">${D.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}<a href="https://commons.wikimedia.org/wiki/File:A350_First_Flight_-_Low_pass_02.jpg" target="_blank" rel="noopener noreferrer">A350 首飞摄影 · Wikimedia Commons ↗</a></div><p class="subtitle" style="margin:15px 0;line-height:1.9">A350 首飞摄影：Don-vip，<a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a>。使用缩略版本，并按界面裁切展示；照片及裁切展示保持相同许可。其他机型仅展示名称与参数，不使用飞机示意图。</p><h2 style="margin:26px 0 12px">哪些属于模拟设定？</h2><div class="report-lines"><div><span>经营数值</span><small>购机价、二手报价、租金、融资、机库、舱位空间、油耗、需求与评分</small></div><div><span>国际情景</span><small>外交合作、冲突、空域限制及影响均为虚构</small></div><div><span>时间规则</span><small>每次结算 7 天；航班按分钟排班；节庆为近似需求窗口</small></div><div><span>飞行限制</span><small>球面距离、6% 航程余量、每周 100 小时排班</small></div><div><span>运行简化</span><small>未模拟航权双边谈判、详细机场性能、ETOPS、改舱停场与实时天气</small></div><div><span>排行榜</span><small>真实名称、模拟分数；不对应任何现实奖项</small></div></div><h2 style="margin:26px 0 10px">收支与破产规则</h2><p class="subtitle" style="line-height:2">航线贡献不扣机队租金、机组薪酬、总部与服务固定费用，完整损益请看财务周报。租赁交付后开始收租，退租返还 80% 押金。维护状态低于 55 自动停飞，检修两周恢复到 100。现金低于 −1,000 万进入清算；更高但为负时，可以通过融资或资产处置救助。停飞航线没有票款和飞行可变成本，但仍承担机队固定支出。</p></section>`;}
function showModal(title,body,sub='',wide=false){if(!$('.modal'))lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><div><h2 id="dialog-title">${title}</h2>${sub?`<p class="subtitle">${sub}</p>`:''}</div><button class="icon-btn" data-action="closeModal" aria-label="关闭" ${needsSetup?'hidden':''}>${ic('close',20)}</button></div><div class="modal-body">${body}</div></section></div>`;const modal=$('.modal'),actions=[...modal.querySelectorAll('.form-actions')].at(-1);if(actions){const form=actions.closest('form');if(form)actions.querySelectorAll('button[type=submit]').forEach(b=>b.setAttribute('form',form.id));const footer=document.createElement('div');footer.className='modal-footer';footer.append(actions);modal.append(footer);}modal.querySelector('button:not([hidden]),input,select')?.focus();}function closeModal(){if(needsSetup)return;const resume=resumeOnNoticeClose;resumeOnNoticeClose=false;stopSimulation();$('#modal-root').innerHTML='';if(viewportNeedsRender){viewportNeedsRender=false;render();}if(lastFocus?.isConnected)lastFocus.focus();if(resume&&E.simulationActive(state)&&!state.pending)simulationTimer=setTimeout(runSimulation,0);}

function countries(){return [...new Set(D.airports.map(a=>a.country))].sort((a,b)=>a==='中国'?-1:b==='中国'?1:a.localeCompare(b,'zh-CN'));}
function countryOptions(selected,all=false){return (all?['全部国家 / 地区',...countries()]:countries()).map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${c==='中国'?'中国内地':esc(c)}</option>`).join('');}
function airportOptionLabel(a){return `${esc(a.city)} · ${esc(/机场$|airport|air base/i.test(a.name)?a.name:a.name+'机场')}（${a.code}）`;}
function cityOptions(country,selected,baseOnly=false){return D.airports.filter(a=>a.country===country&&(!baseOnly||!state.hubs.some(h=>h.code===a.code))).sort((a,b)=>a.city.localeCompare(b.city,'zh-CN')).map(a=>`<option value="${a.code}" ${a.code===selected?'selected':''}>${airportOptionLabel(a)}</option>`).join('');}
function planeOptions(from,selected){return E.prioritizedFleet(state).filter(p=>E.planeAvailable(state,p)&&E.planeBase(state,p)===from).map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${E.modelName(p.model)} · B-YS${String(p.id).padStart(3,'0')} · ${E.usedHours(state,p.id).toFixed(1)} 小时 / 周</option>`).join('');}
function routeCount(rows){return new Set(rows.map(r=>[r.from,r.to].sort().join('-'))).size;}
function routeStatus(from,to){const rows=E.routeAssignments(state,{from,to}),active=rows.filter(r=>r.active);return {rows,active,freq:active.reduce((n,r)=>n+r.freq,0),planes:new Set(active.map(r=>r.plane).filter(Boolean)).size};}
function routeCityOptions(country,from,selected){return D.airports.filter(a=>a.country===country&&a.code!==from).sort((a,b)=>a.city.localeCompare(b.city,'zh-CN')).map(a=>{const st=routeStatus(from,a.code);return `<option value="${a.code}" ${a.code===selected?'selected':''}>${airportOptionLabel(a)} · ${st.rows.length?`已开 ${st.freq} 班往返/周${!st.active.length?'（暂停）':''}`:'未开通'}</option>`;}).join('');}
function routeExistingSummary(){const f=$('#route-form'),st=routeStatus(f.elements.from.value,f.elements.to.value),box=$('#route-existing');box.innerHTML=st.rows.length?`<strong>已开通 · 每周 ${st.freq} 班往返 · ${st.planes} 架飞机</strong><span>${st.rows.length-st.active.length?`${st.rows.length-st.active.length} 个配机计划暂停。`:''}可调现有班次，或用另一架飞机增班。</span>${button('查看已有配机','routeGroup','','data-from="'+f.elements.from.value+'" data-to="'+f.elements.to.value+'"','tiny')}`:'<span>尚未开通这条航线。</span>';}
function selectAdditionalPlane(){const f=$('#route-form');if(f.dataset.id)return;const rows=E.routeAssignments(state,{from:f.elements.from.value,to:f.elements.to.value});if(rows.some(r=>r.plane===+f.elements.plane.value)){const p=state.fleet.find(p=>E.planeAvailable(state,p)&&E.planeBase(state,p)===f.elements.from.value&&!rows.some(r=>r.plane===p.id));if(p)f.elements.plane.value=p.id;}}
let routeGroupFrom='',routeGroupTo='',routeGroupPage=0;
function routeGroup(from,to,page=0){routeGroupFrom=from;routeGroupTo=to;const st=routeStatus(from,to);routeGroupPage=Math.max(0,Math.min(page,st.rows.length-1));showModal(`${E.ap(from).city} ⇄ ${E.ap(to).city}`,`<p>合计每周 ${st.freq} 班往返 · ${st.planes} 架飞机。每架飞机分别安排班次与时刻。</p><div class="advisor-pager">${button('上一架','routeGroupPage','','data-delta="-1" '+(!routeGroupPage?'disabled':''))}<span>${st.rows.length?routeGroupPage+1:0} / ${st.rows.length}</span>${button('下一架','routeGroupPage','','data-delta="1" '+(routeGroupPage>=st.rows.length-1?'disabled':''))}</div>${routeCards(st.rows.slice(routeGroupPage,routeGroupPage+1))}<div class="form-actions">${button('返回','closeModal')}${button('增派飞机','addRoutePlane','plus',`data-from="${from}" data-to="${to}"`,'primary')}</div>`,'同一航线，多机协同运营');}
function routeModal(id=null,to=null,plane=null,base=null){const r=state.routes.find(x=>x.id===id);let from=r?.from||base||(plane?E.planeBase(state,state.fleet.find(p=>p.id===plane)):state.base),selectedTo=r?.to||to||D.airports.find(a=>a.region==='CN'&&a.code!==from&&!state.routes.some(x=>x.from===from&&x.to===a.code))?.code||'PVG',country=E.ap(selectedTo).country;showModal(r?'调整航线计划':'开通一条新航线',`<form id="route-form" data-id="${id||''}"><div class="form-grid"><label class="field full">出发基地<select name="from" ${r?'disabled':''}>${state.hubs.map(h=>`<option value="${h.code}" ${h.code===from?'selected':''}>${esc(E.ap(h.code).country)} · ${airportOptionLabel(E.ap(h.code))}</option>`).join('')}</select></label><label class="field">目的地国家 / 地区<select name="country" ${r?'disabled':''}>${countryOptions(country)}</select></label><label class="field">目的地城市 / 机场<select name="to" ${r?'disabled':''}>${routeCityOptions(country,from,selectedTo)}</select></label><div id="route-existing" class="route-existing" data-route-stage="0"></div><label class="field">经停国家 / 地区<select name="viaCountry"><option value="">不经停 · 直飞</option>${countryOptions(r?.via?E.ap(r.via).country:'美国')}</select></label><label class="field">经停城市 / 机场<select name="via">${r?.via?cityOptions(E.ap(r.via).country,r.via):'<option value="">不经停</option>'}</select></label><label class="field full">每次经停地面时间（分钟）<input name="stopMinutes" type="number" min="60" max="720" step="1" aria-describedby="stop-time-hint" value="${r?.stopMinutes||90}"><small id="stop-time-hint">至少 60 分钟（60 mins），最多 720 分钟；默认 90 分钟。直飞时不计经停时间。<br>同机经停往返，去程与返程均停留；无需设立分基地。游戏简化航权与过境手续。</small></label><label class="field full">执飞飞机<select name="plane">${planeOptions(from,r?.plane||plane)}</select></label><label class="field">每周往返班次<input name="freq" type="number" min="1" max="28" value="${r?.freq||7}" required></label><label class="field">票价策略<select name="price">${[.65,.75,.85,1,1.15,1.3,1.5,1.8].map(v=>`<option value="${v}" ${v===(r?.price||1)?'selected':''}>${v===1?'标准票价':v<1?'优惠':'溢价'} · ${Math.round(v*100)}%</option>`).join('')}</select></label></div><div id="route-quote"></div><div class="form-actions">${button('取消','closeModal')}<button type="submit" class="btn primary" id="save-route">${r?'保存航线计划':'支付开航费用并开通'}</button></div></form>`,r?'变更班次或执飞机会重新自动排班；可在「航班排班」调整具体时间。':'新航线：国内 160 万，国际及地区 500 万。同航线增派免重复开航费；新增经停点另付 200 万。同航线各飞机自动错峰排班。',true);initRouteWizard();if(!r?.via)$('#route-form').elements.viaCountry.value='';if(!r&&!plane)selectAdditionalPlane();routeQuote();if(r)setRouteStage(2);}
function hubModal(){showModal('让新的城市，成为你的基地',`<p>国内分基地：口碑 65，投入 2,500 万。海外及地区分基地：国际资质、口碑 70、已交付飞机 5 架，投入 6,000 万。开设后可调入飞机，在当地始发运营。</p><form id="hub-form"><div class="form-grid"><label class="field">国家 / 地区<select name="country">${countryOptions('中国')}</select></label><label class="field">城市 / 机场<select name="code">${cityOptions('中国',null,true)}</select></label></div><p id="hub-quote" class="subtitle" style="margin-top:15px">国内基地每周固定开支 6 万；海外基地 15 万。游戏简化外国经营资质与航权审批。</p><div class="form-actions"><button class="btn primary" type="submit">投资并设立分基地</button></div></form>`,'可在全球已收录的城市设分基地。');}
function rebaseModal(id){const p=state.fleet.find(p=>p.id===id);showModal('调往另一座基地',`<p>${E.modelName(p.model)} 当前驻地 ${E.ap(E.planeBase(state,p)).city}。需先关闭或改派它的全部航线。在役飞机调机需要一周，按航程收取调机费用；待交付订单可免费更改进驻基地。</p><form id="rebase-form" data-id="${id}"><label class="field">目标基地<select name="code">${state.hubs.filter(h=>h.code!==E.planeBase(state,p)).map(h=>`<option value="${h.code}">${E.ap(h.code).country} · ${E.ap(h.code).city} · ${h.code} · ${p.delivery?'免费':money(.1+E.block(E.planeBase(state,p),h.code)*E.model(p.model).fuel*.0062)}</option>`).join('')}</select></label><div class="form-actions"><button class="btn primary" type="submit" ${state.hubs.length<2?'disabled':''}>确认调往基地</button></div></form>`,'先在「公司发展」增设基地，再调入飞机。');}
function insights(){const from=state.hubs.some(h=>h.code===insightBase)?insightBase:state.base;const rows=D.airports.filter(a=>a.code!==from&&(insightCountry==='全部国家 / 地区'||a.country===insightCountry)).map(a=>E.marketStats(state,from,a.code)).sort((a,b)=>insightSort==='competition'?b.rivals.length-a.rivals.length:insightSort==='demand'?b.demand-a.demand:insightSort==='score'?b.score-a.score:b.gap-a.gap);const visible=pageItems(rows,'insights');return `${head('MARKET INTELLIGENCE','找到旅客，比追着飞机跑更重要。','比较市场需求、预计运力与竞争，从机会出发规划航网。')}${stats([['可研究机场',D.airports.length,'座',`${countries().length} 个国家或地区`,'globe'],['当前筛选市场',rows.length,'个',`${E.ap(from).city}始发市场`,'route'],['存在座位缺口',rows.filter(r=>r.gap>0).length,'个','按本周事件与模拟运力估算','people'],['需求最旺城市',rows.length?E.ap([...rows].sort((a,b)=>b.demand-a.demand)[0].to).city:'—','','市场总需求，不等于你的销量','chart']])}<div class="market-controls"><label class="field">始发基地<select id="insight-base">${state.hubs.map(h=>`<option value="${h.code}" ${h.code===from?'selected':''}>${E.ap(h.code).city} · ${h.code}</option>`).join('')}</select></label><label class="field">目的地国家 / 地区<select id="insight-country">${countryOptions(insightCountry,true)}</select></label><label class="field">排序<select id="insight-sort">${[['gap','座位缺口优先'],['demand','总需求优先'],['competition','竞争最激烈'],['score','机会分优先']].map(([k,v])=>`<option value="${k}" ${insightSort===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="notice">模拟市场：需求受城市规模参数、距离与节庆影响；竞争运力按资料库中航司的枢纽与市场覆盖估算，不代表真实航班数据。正缺口是市场机会，并不保证你能售出全部座位。筛选与排序覆盖全部市场。</div>${pager('insights')}<section class="panel table-scroll insight-table"><table><thead><tr><th>目的地</th><th>周需求 / 座位供给</th><th>预计座位缺口</th><th>竞争</th><th>距离 / 机会分</th><th>规划</th></tr></thead><tbody>${visible.map(r=>{const a=E.ap(r.to),existing=state.routes.find(x=>[x.from,x.to].sort().join()===[from,r.to].sort().join());return `<tr><td><strong>${esc(a.city)} · ${a.code}</strong><small style="display:block">${a.country}</small></td><td>${r.demand.toLocaleString()} / ${r.supply.toLocaleString()}<small style="display:block">自家运力 ${r.own.toLocaleString()}</small></td><td class="${r.gap>0?'positive':'negative'}">${r.closed?'区域停航':r.gap.toLocaleString()}</td><td><span class="tag ${r.rivals.length>=4?'amber':''}">${r.competition} · ${r.rivals.length} 家</span><small class="rival-names">${r.rivals.map(x=>esc(x.name)).join('、')||'暂无主要模拟对手'}</small></td><td>${r.km.toLocaleString()} km<small style="display:block">机会分 ${r.score} / 100</small></td><td>${existing?button('管理现有航线','editRoute','',`data-id="${existing.id}"`,'tiny'):button('规划航线','planMarket','',`data-from="${from}" data-to="${r.to}"`,'tiny')}</td></tr>`}).join('')}</tbody></table></section>`;}
function clockLabel(base,minute,airport){const c=E.localClock(state,base,minute,airport);return `${c.date} 周${c.weekday} ${c.time}`;}
function timetable(){return `<section class="${scheduleMode==='route'?'route-schedule-shell':''}"><nav class="schedule-mode" aria-label="排班查看方式">${[['route','按航线看'],['plane','按飞机看']].map(([key,label])=>button(label,'scheduleMode','',`data-mode="${key}" aria-pressed="${scheduleMode===key}"`,scheduleMode===key?'primary':'')).join('')}</nav>${scheduleMode==='route'?routeTimetableView():aircraftTimetable()}</section>`;}
let calendarModel=null,calendarKey='',calendarScroll={},calendarDetailPage=0,calendarDetailRows=[];
function calendarReference(){return scheduleDirection==='back'?scheduleTo:scheduleFrom;}
function calendarRemember(){const el=$('.route-calendar-scroll'),col=$('.calendar-day-body');if(!el||!col)return;const width=col.getBoundingClientRect().width;if(el.dataset.columnWidth&&Math.abs(Number(el.dataset.columnWidth)-width)>.5)return;calendarScroll[el.dataset.key]={day:+el.dataset.first+el.scrollLeft/width,top:el.scrollTop};}
function calendarRestore(){const el=$('.route-calendar-scroll'),col=$('.calendar-day-body');if(!el||!col)return;const saved=calendarScroll[el.dataset.key],first=+el.dataset.first;el.dataset.columnWidth=col.getBoundingClientRect().width;el.scrollLeft=((saved?.day??0)-first)*col.getBoundingClientRect().width;el.scrollTop=saved?.top??Math.max(0,(calendarModel.rows[0]?.minute??420)*1.6);if(el.dataset.bound)return;el.dataset.bound='1';el.addEventListener('scroll',()=>{if(Math.abs(Number(el.dataset.columnWidth)-col.getBoundingClientRect().width)>.5)return;calendarRemember();const idx=Math.floor(el.scrollLeft/col.getBoundingClientRect().width),d=calendarModel.days[idx];if(d&&$('#calendar-day'))$('#calendar-day').value=d.day;},{passive:true});}
let calendarDrag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.route-calendar-scroll');if(!el||e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,select'))return;calendarDrag={el,id:e.pointerId,x:e.clientX,y:e.clientY,left:el.scrollLeft,top:el.scrollTop};});
document.addEventListener('pointermove',e=>{const d=calendarDrag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.hypot(dx,dy)<6)return;d.el.setPointerCapture(e.pointerId);d.el.scrollLeft=d.left-dx;d.el.scrollTop=d.top-dy;e.preventDefault();});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,()=>{calendarDrag=null;});
function calendarGo(day){const el=$('.route-calendar-scroll'),col=$('.calendar-day-body');if(!el||!col)return;el.scrollTo({left:(day-Number(el.dataset.first))*col.getBoundingClientRect().width,behavior:'instant'});calendarRemember();}
function routeCalendar(rows){
 const reference=calendarReference();calendarModel=AIR_CALENDAR.project(state,rows,reference,E);calendarKey=[state.date,scheduleFrom,scheduleTo,scheduleDirection].join('|');const days=calendarModel.days,airport=E.ap(reference),offset=airport.utcOffset||0;
 return `<div class="calendar-navigation"><span>时间轴：${esc(airport.city)} UTC${offset>=0?'+':''}${offset}${scheduleDirection==='both'?' · 返程已换算':''}</span><label><span class="sr-only">跳到日期</span><select id="calendar-day" aria-label="跳到日期">${days.map(d=>`<option value="${d.day}">${d.date} 周${d.weekday}</option>`).join('')}</select></label></div><div class="route-calendar-scroll" role="region" aria-label="每周航班日历，可左右查看日期、上下查看时间" tabindex="0" data-key="${esc(calendarKey)}" data-first="${days[0].day}"><div class="route-calendar-grid" style="--calendar-days:${days.length}"><div class="calendar-corner">时间</div>${days.map(d=>`<div class="calendar-day-heading ${d.day===0?'current':''}"><strong>周${d.weekday}</strong><span>${d.date}${d.day<0||d.day>6?' · 跨周':''}</span><small>${d.items.length} 班</small></div>`).join('')}<div class="calendar-time-column">${Array.from({length:25},(_,h)=>`<span style="top:${h*96}px">${String(h).padStart(2,'0')}:00</span>`).join('')}</div>${days.map((d,di)=>`<div class="calendar-day-body" data-day="${d.day}">${d.groups.map((g,gi)=>{const t=g.rows[0].flight,multiple=g.rows.length>1;return `<button class="calendar-flight ${t.from===scheduleFrom?'outbound':'inbound'} ${!t.ready?'not-ready':''}" style="top:${g.minute*1.6}px" data-action="calendarFlight" data-day-index="${di}" data-group="${gi}" aria-label="${d.date} 周${d.weekday} ${g.rows.map(r=>r.time).join('、')}，${multiple?g.rows.length+' 班航班':'B-YS'+String(t.plane).padStart(3,'0')}，查看航班详情"><strong>${g.rows[0].time}${multiple?' · '+g.rows.length+' 班':''}</strong><span>${multiple?'密集时段 · 展开全部':t.from+' → '+t.to}</span><small>${multiple?g.rows.slice(1,3).map(r=>r.time).join(' / ')+(g.rows.length>3?' …':''):'B-YS'+String(t.plane).padStart(3,'0')+' · '+esc(t.model)}</small></button>`;}).join('')}${!d.items.length?'<span class="calendar-day-empty">当日无航班</span>':''}</div>`).join('')}</div></div><p class="calendar-help">左右滑动看日期，上下滑动看时间 · 点击航班查看详情与调整</p>`;
}
function calendarFlightDetail(di,gi,page=0){
 if(di!==null){calendarDetailRows=calendarModel.days[di]?.groups[gi]?.rows||[];calendarDetailPage=0;}else calendarDetailPage=page;
 const row=calendarDetailRows[calendarDetailPage];if(!row)return;const t=row.flight,c=E.cabinOf(state.fleet.find(p=>p.id===t.plane)),wide=E.cabinRules(E.model(t.model)).first;
 showModal('航班详情',`<div class="calendar-detail"><span class="tag">${t.ready?(t.manual?'手动锁定':'自动排班'):'预排 · 飞机未就绪'}</span><h3>${airportOptionLabel(E.ap(t.from))} → ${airportOptionLabel(E.ap(t.to))}</h3><dl><dt>起飞 · 出发地时间</dt><dd>${clockLabel(t.base,t.dep,t.from)}</dd><dt>抵达 · 到达地时间</dt><dd>${clockLabel(t.base,t.arr,t.to)}</dd><dt>执飞飞机</dt><dd>${esc(E.modelName(t.model))} · B-YS${String(t.plane).padStart(3,'0')}</dd><dt>客舱布局</dt><dd>经济 ${c.economy} · 商务 ${c.business}${wide?' · 头等 '+c.first:''}</dd>${t.via?`<dt>经停</dt><dd>${airportOptionLabel(E.ap(t.via))}</dd>`:''}</dl></div><div class="form-actions calendar-detail-actions">${calendarDetailRows.length>1?`<div class="calendar-detail-pager">${button('上一班','calendarDetailPrev','',calendarDetailPage===0?'disabled':'')}<span>${calendarDetailPage+1} / ${calendarDetailRows.length}</span>${button('下一班','calendarDetailNext','',calendarDetailPage===calendarDetailRows.length-1?'disabled':'')}</div>`:''}${button('关闭','closeModal')}${button('管理舱位','cabin','seat',`data-id="${t.plane}"`)}${button('调整时刻','manualSchedule','clock',`data-id="${t.route}"`,'primary')}</div>`,'起降分别显示机场当地时间；时间轴以所选参考机场为准');
}
function routeTimetableView(){
 const pairs=state.routes.filter(r=>!r.awaitingAircraft),fromCodes=[...new Set(pairs.flatMap(r=>[r.from,r.to]))];
 if(!fromCodes.includes(scheduleFrom))scheduleFrom=fromCodes.includes(state.base)?state.base:fromCodes[0]||'';
 const destinations=[...new Set(pairs.filter(r=>r.from===scheduleFrom||r.to===scheduleFrom).map(r=>r.from===scheduleFrom?r.to:r.from))];
 if(!destinations.includes(scheduleTo))scheduleTo=destinations[0]||'';
 let flights=[],error='';if(scheduleFrom&&scheduleTo)try{flights=E.routeTimetable(state,scheduleFrom,scheduleTo);}catch(e){error=e.message;}
 const rows=flights.filter(t=>scheduleDirection==='both'||(scheduleDirection==='out'?t.from===scheduleFrom:t.from===scheduleTo)),close=flights.filter(t=>t.gap!==null&&t.gap<60).length;
 return `<div class="route-schedule-bar"><button class="btn route-choice" data-action="chooseScheduleRoute" aria-label="更换航线"><strong>${scheduleFrom?esc(E.ap(scheduleFrom).city)+' '+scheduleFrom:'暂无航线'} ⇄ ${scheduleTo?esc(E.ap(scheduleTo).city)+' '+scheduleTo:'—'}</strong><small>更换航线</small></button><div class="route-calendar-actions">${scheduleTo?button('舱位','routeCabins','seat',`data-from="${scheduleFrom}" data-to="${scheduleTo}" aria-label="管理本航线舱位"`)+button('自动排班','autoRouteSchedule','clock','aria-label="联动自动排班"','primary'):''}</div></div><div class="route-schedule-filters"><div class="tabs" aria-label="航班方向">${[['out','去程'],['back','返程'],['both','双向']].map(([key,label])=>button(label,'scheduleDirection','',`data-direction="${key}" aria-pressed="${scheduleDirection===key}"`,scheduleDirection===key?'primary':'')).join('')}</div><p class="route-schedule-summary">${new Set(flights.map(t=>t.plane)).size} 架飞机 · ${rows.length} 班 / 周${close?' · 存在密集班次':''}</p></div>${error?`<div class="notice">${esc(error)}</div>`:''}${scheduleTo?routeCalendar(rows):'<div class="empty">先开通航线，再在这里查看每周航班。</div>'}`;
}
function chooseScheduleRoute(){const routes=state.routes.filter(r=>!r.awaitingAircraft),codes=[...new Set(routes.flatMap(r=>[r.from,r.to]))];showModal('选择航线时刻表',`<label class="field">出发机场<select id="route-schedule-from">${codes.map(c=>`<option value="${c}" ${c===scheduleFrom?'selected':''}>${airportOptionLabel(E.ap(c))}</option>`).join('')}</select></label><label class="field" style="margin-top:16px">到达机场<select id="route-schedule-to"></select></label><div class="form-actions">${button('取消','closeModal')}${button('查看时刻表','applyScheduleRoute','','','primary')}</div>`,'汇总这两个机场之间所有飞机的航班。');scheduleDestinationOptions(scheduleTo);}
function scheduleDestinationOptions(selected){const from=$('#route-schedule-from').value,codes=[...new Set(state.routes.filter(r=>!r.awaitingAircraft&&(r.from===from||r.to===from)).map(r=>r.from===from?r.to:r.from))];$('#route-schedule-to').innerHTML=codes.map(c=>`<option value="${c}" ${c===selected?'selected':''}>${airportOptionLabel(E.ap(c))}</option>`).join('');}
function aircraftTimetable(){const p=state.fleet.find(p=>p.id===schedulePlane)||E.prioritizedFleet(state)[0];let slots=[],error='';if(p)try{slots=E.schedulePlan(state,p.id);}catch(e){error=e.message;}const base=p?E.planeBase(state,p):state.base;return `${head('FLIGHT SCHEDULING','每一程，都有明确的起降时间。','全天 24 小时自动排班，优先白天、必要时夜航；返程、经停与地面周转一并安排，手动锁定时刻保持不变。',p?button('管理航线 / 班次','planeRoutes','route',`data-id="${p.id}"`)+button('飞机联动排班','autoSchedule','clock',`data-id="${p.id}"`,'primary'):'')}<div class="market-controls"><label class="field">选择飞机<select id="schedule-plane">${E.prioritizedFleet(state).map(x=>`<option value="${x.id}" ${x.id===p?.id?'selected':''}>${E.modelName(x.model)} · B-YS${String(x.id).padStart(3,'0')} · 驻地 ${E.planeBase(state,x)}</option>`).join('')}</select></label><div class="schedule-key">${p?`${E.ap(base).city}驻地 · 周飞行 ${E.usedHours(state,p.id).toFixed(1)} / 100 小时 · 每次周转至少 ${E.turnMinutes(p)} 分钟`:''}</div></div>${error?`<div class="notice">${error}</div>`:''}${p&&!E.planeAvailable(state,p)?'<div class="notice">飞机当前未就绪，以下为预排计划，交付或维护完成后才实际运营。</div>':''}<div class="week-scroll"><div class="week-grid">${Array.from({length:7},(_,d)=>`<section class="day-column"><h3>周${'一二三四五六日'[d]}</h3>${slots.filter(t=>Math.floor(t.start/1440)===d).map(t=>`<button class="flight-slot ${t.manual?'locked':''}" data-action="manualSchedule" data-id="${t.route}"><small>${t.manual?'手动锁定':'自动排班'}</small><strong>${t.from} ⇄ ${t.to}</strong>${t.via?`<span>经 ${t.via}</span>`:''}<span>${E.localClock(state,base,t.start,base).time} 出发</span><span>${clockLabel(base,t.end,base)} 返回</span></button>`).join('')||'<p>无始发航班</p>'}</section>`).join('')}</div></div><p class="info-inline" style="margin:12px 0">上方按基地出发日排列；下方逐航段显示机场当地时间。采用机场标准时区，暂不模拟夏令时、宵禁或机组执勤上限。跨日往返会占用后续日期，不能重叠排班。</p><section class="panel table-scroll"><table><thead><tr><th>航段 / 飞机</th><th>出发机场当地时间</th><th>到达机场当地时间</th><th>飞行时长</th><th>计划来源</th></tr></thead><tbody>${slots.flatMap(t=>t.segments.map(l=>({...t,...l}))).sort((a,b)=>a.dep-b.dep).map(t=>`<tr><td><strong>${t.a} → ${t.b}</strong><small style="display:block">${E.ap(t.a).city} → ${E.ap(t.b).city}</small></td><td>${clockLabel(base,t.dep,t.a)}</td><td>${clockLabel(base,t.arr,t.b)}</td><td>${Math.floor(t.duration/60)} 小时 ${t.duration%60} 分</td><td>${button(t.manual?'修改手动时刻':'手动调整','manualSchedule','',`data-id="${t.route}"`,'tiny')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">请先为这架飞机开通航线。</td></tr>'}</tbody></table></section>`;}
function manualSchedule(id){const r=state.routes.find(r=>r.id===id);if(!r)return;try{const slots=E.schedulePlan(state,r.plane).filter(t=>t.route===id);showModal(`${r.from} ⇄ ${r.to} · 手动时刻`,`<form id="schedule-form" data-id="${id}"><p>按出发基地当地时间设置每次往返的首班起飞时间。可调整目的地停留时间，返程会在抵达后按该时长起飞。锁定这条航线后，其余自动班次会避让；已锁定班次之间不能冲突。</p><div class="schedule-fields">${slots.map((t,i)=>`<div><span>往返 ${i+1}</span><label class="field">星期<select name="day-${i}">${Array.from({length:7},(_,d)=>`<option value="${d}" ${Math.floor(t.start/1440)===d?'selected':''}>周${'一二三四五六日'[d]}</option>`).join('')}</select></label><label class="field">起飞时间<input name="time-${i}" type="time" value="${E.localClock(state,r.from,t.start,r.from).time}" required></label><label class="field">目的地停留（分钟）<input name="ground-${i}" type="number" min="${E.turnMinutes(state.fleet.find(p=>p.id===r.plane))}" max="1440" step="1" value="${t.turn}" required></label></div>`).join('')}</div><div id="schedule-quote" aria-live="polite"></div><div class="form-actions">${button('取消','closeModal')}<button class="btn primary" type="submit" id="save-schedule">保存并锁定时刻</button></div></form>`,'时间精确到分钟 · 自动检查飞机占用与地面周转',true);scheduleQuote();}catch(e){toast(e.message);}}
function scheduleInput(){const f=$('#schedule-form'),r=state.routes.find(r=>r.id===+f.dataset.id);return Array.from({length:r.freq},(_,i)=>{const [h,m]=f.elements['time-'+i].value.split(':').map(Number);return {day:+f.elements['day-'+i].value,departure:h*60+m,turnaround:Number(f.elements['ground-'+i].value)};});}
function scheduleQuote(){const f=$('#schedule-form');if(!f)return;const r=state.routes.find(r=>r.id===+f.dataset.id);try{const schedule=scheduleInput();const slots=E.schedulePlan({...state,routes:state.routes.map(x=>x.id===r.id?{...x,schedule}:x)},r.plane);$('#schedule-quote').innerHTML=`<div class="quote"><div class="quote-note">时间检查通过。整架飞机共安排 ${slots.length} 次往返，没有重叠；每次周转至少 ${E.turnMinutes(state.fleet.find(p=>p.id===r.plane))} 分钟。</div></div>`;$('#save-schedule').disabled=false;}catch(e){$('#schedule-quote').innerHTML=`<div class="notice" style="margin-top:18px">${esc(e.message)}</div>`;$('#save-schedule').disabled=true;}}

function transitSuggestions(r,m){const direct=E.distance(r.from,r.to),range=m.range*.94;if(E.routeLegs(r).every(l=>l.km<=range))return '';const options=E.transitOptions(state,r.from,r.to,r.plane);return `<section class="transit-options"><h3>${direct>range?'直飞航程不足 · 推荐经停':'当前经停航段超出航程 · 其他方案'}</h3><p>${esc(E.modelName(m))} 的单段运营上限 ${Math.floor(range).toLocaleString()} km；直飞距离 ${direct.toLocaleString()} km。按实际飞行总距离排序，已排除本周停航机场。</p>${options.length?options.map(o=>`<button type="button" class="transit-option ${r.via===o.via?'selected':''}" data-action="chooseStop" data-code="${o.via}"><strong>${E.ap(o.via).city} · ${o.via}</strong><span>${o.legs.map(l=>l.km.toLocaleString()).join(' + ')} km</span><small>单程约 ${o.hours.toFixed(1)} 小时，含 90 分钟经停</small></button>`).join(''):'<p class="negative">目前没有同时满足两段航程且开放的经停点，请换长航程飞机。也可在上方手动选择其他机场检查。</p>'}<p>仅检查航程与停航限制；班次、驻地、资质及周排班会在下方继续校验。可在上方自选任意经停机场。</p></section>`;}
function initRouteWizard(){const form=$('#route-form');routeStage=0;form.querySelectorAll('.form-grid>.field').forEach(label=>{const name=label.querySelector('input,select').name;label.dataset.routeStage=['viaCountry','via','stopMinutes'].includes(name)?1:(['freq','price'].includes(name)||name==='plane'&&form.dataset.id)?2:0;});$('#route-quote').dataset.routeStage=2;const nav=document.createElement('div');nav.className='wizard-tabs';nav.innerHTML=['出发与目的地','直飞或经停','班次与报价'].map((t,i)=>`<button type="button" data-action="routeStage" data-stage="${i}">${i+1}. ${t}</button>`).join('');form.prepend(nav);const actions=$('.modal-footer .form-actions');actions.innerHTML=`${button('取消','closeModal')}${button('上一步','routeBack')}${button('下一步','routeNext','arrow','','primary')}<button type="submit" form="route-form" id="save-route" class="btn primary">${form.dataset.id?'保存航线计划':'支付并开通航线'}</button>`;setRouteStage(0);}
function setRouteStage(stage){routeStage=Math.max(0,Math.min(2,stage));$('.modal').dataset.routeStage=routeStage;$('#route-form').querySelectorAll('[data-route-stage]').forEach(e=>e.hidden=Number(e.dataset.routeStage)!==routeStage);$('#route-form').querySelectorAll('.wizard-tabs button').forEach(b=>b.setAttribute('aria-current',Number(b.dataset.stage)===routeStage?'step':'false'));$('.modal-footer [data-action=routeBack]').hidden=routeStage===0;$('.modal-footer [data-action=routeNext]').hidden=routeStage===2;$('#save-route').hidden=routeStage!==2;$('.modal-body').scrollTop=0;}
function cabinPanel(stage){const f=$('#cabin-form');[...f.children].filter(e=>e.id!=='cabin-quote').forEach(e=>e.hidden=stage===1);$('#cabin-quote').hidden=stage===0;$('.modal-footer [data-action=cabinReview]').hidden=stage===1;$('.modal-footer [data-action=cabinBack]').hidden=stage===0;$('#save-cabin').hidden=stage===0;$('.modal-body').scrollTop=0;}
function routeQuote(){let form=$('#route-form');if(!form)return;routeExistingSummary();let obj=Object.fromEntries(new FormData(form));if(!form.elements.plane.value){$('#route-quote').innerHTML='<p class="notice" style="margin-top:15px">此基地没有可用飞机。请先在机队管理中调入飞机，等待交付或完成检修。</p>';$('#save-route').disabled=true;return;}$('#save-route').disabled=false;obj.from=form.elements.from.value;obj.to=form.elements.to.value;const old=state.routes.find(r=>r.id===+form.dataset.id);let r={...old,...obj,via:obj.via||null,plane:+obj.plane,freq:+obj.freq,price:+obj.price,stopMinutes:obj.via?+obj.stopMinutes:0,active:true};if(old&&(r.freq!==old.freq||r.plane!==old.plane||r.via!==old.via||r.stopMinutes!==(old.stopMinutes||0)))r.schedule=null;if(r.from===r.to){$('#save-route').disabled=true;$('#route-quote').innerHTML='<p class="notice" style="margin-top:15px">请将目的地设为不同机场。</p>';return;}let validation='';try{E.validateRoute(state,r,+form.dataset.id||undefined);}catch(err){validation=err.message;}$('#save-route').disabled=!!validation;const st=routeStatus(r.from,r.to),fee=old?(r.via&&r.via!==old.via?2:0):E.routeSetupCost(r,state);$('#save-route').textContent=old?'保存航线计划':st.rows.length?(fee?'支付并增派飞机':'保存增派计划'):'支付并开通航线';const e=E.estimate(state,r),p=state.fleet.find(x=>x.id===r.plane),m=E.model(p.model),legs=E.routeLegs(r),km=legs.reduce((n,l)=>n+l.km,0),hours=E.usedHours(state,r.plane,+form.dataset.id)+e.hours,range=legs.some(l=>l.km>m.range*.94),intl=E.routeInternational(r),load=E.scheduleLoad({...state,routes:[...state.routes.filter(x=>x.id!==+form.dataset.id),{...r,id:+form.dataset.id||-1}]},r.plane);$('#route-quote').innerHTML=`${transitSuggestions(r,m)}<div class="quote"><div class="quote-note"><strong>${r.via?'经停方案：'+E.ap(r.via).city:'直飞方案 · 不经停'}</strong>${!r.via&&!range?' · 当前飞机航程满足要求':''}</div><div class="quote-note">${st.rows.length?`本线现有 ${st.freq} 班往返/周 · ${st.planes} 架飞机；本次${old?'调整':'新增'} ${r.freq} 班往返/周。`:'新开航线。'} 本次费用 ${money(fee)}。</div><div><small>单程实际航程${r.via?'（含经停）':''}</small>${km.toLocaleString()} km</div><div><small>预计客座率 / 经济舱单程票价</small>${pct(e.load)} / ¥${e.fare}</div><div><small>预计周航线贡献</small><strong class="${e.profit>=0?'positive':'negative'}">${money(e.profit,true)}</strong></div><div><small>飞机合计周飞行时间</small><span class="${hours>100?'negative':''}">${hours.toFixed(1)} / 100 小时</span></div><div><small>含经停与周转的占用时间</small><span class="${load.total>168?'negative':''}">${load.total.toFixed(1)} / 168 小时</span></div><div><small>参考运营航程</small><span class="${range?'negative':''}">${Math.floor(m.range*.94).toLocaleString()} km</span></div><div><small>同市场竞争航司</small>${E.competitors(r).length} 家</div><div class="quote-note">100 小时限制仅计算飞行；排班还需预留经停与地面周转，并避开手动锁定时刻。自动排班优先 07:00 起飞，必要时使用夜间时段。<br>${r.via?`经 ${E.ap(r.via).city}：${legs.map(l=>`${l.from} → ${l.to} ${l.km.toLocaleString()} km`).join(' · ')}；单程含经停 ${(E.routeHours(r)+E.stopMinutes(r)/60).toFixed(1)} 小时。经停带来额外机场费并使需求下调 18%，通程旅客只计一次。<br>`:''}${validation?'⚠ '+esc(validation)+' ':''}${range?'⚠ 航程不足。 ':''}${hours>100?'⚠ 排班超限，请减班。 ':''}${intl&&!state.license?'⚠ 需要国际及地区资质。 ':''}${Object.entries(e.classes).map(([k,v])=>`${({economy:'经济',business:'商务',first:'头等'})[k]} ${v.pax} 人次 × ¥${v.fare}`).join(' · ')}。估算已考虑本周事件，未扣租金、机组及总部固定费用。客流与票价采用游戏模型。</div></div>`;}
function leaseDetail(id){const p=state.fleet.find(p=>p.id===id);if(!p||p.mode!=='lease')return;const c=E.leaseInfo(p,state),l=E.lessor(c.lessor),routes=state.routes.filter(r=>r.plane===id);showModal('租约 · '+E.modelName(p.model),`<span class="tag">${esc(l.name)} · 游戏虚构</span><p class="advisor-reason">${leaseTerms(E.model(p.model),l)}</p><div class="quote"><div><small>已交押金</small>${money(c.depositPaid)}</div><div><small>周租金</small>${money(E.weeklyLease(p))}</div><div><small>合同到期周</small>第 ${c.startWeek+c.term} 周</div><div><small>关联航线</small>${routes.length} 条</div></div>${c.recall?`<p class="notice">${esc(c.recall.reason)}：第 ${c.recall.dueWeek} 周周${'一二三四五六日'[c.recall.day]}零时收回；当周未用 ${7-c.recall.day}/7 天租金 ${money(E.weeklyLease(p)*(7-c.recall.day)/7)}、押金 ${money(c.depositPaid)} 将在该周结算返还。</p>`:'<p>目前没有收回通知。收回风险、租金与通知期限均为游戏规则。</p>'}<p>关联航线：${routes.map(r=>r.from+' ⇄ '+r.to).join('、')||'暂无'}。收回后保留航线并暂停执飞，你可以改派可用飞机。</p><div class="form-actions">${button('关闭','closeModal')}${button('管理航线','navigate','route','data-target="routes"','primary')}</div>`,'按实际占用天数计租 · 退款在周结算入账');}
function leaseTerms(m,l){return `每周租金 ${money(m.lease*l.factor)}，租期 ${l.term} 周；出租方提前收回至少提前 ${l.notice} 周通知。持有 13 周后，每周模拟提前收回概率 ${(l.risk*100).toFixed(2)}%。出租方收回时押金全退，周租按实际占用天数计费；服务配置及改装费不退。玩家主动退租仍返还 80% 押金。`;}
function acquisition(id,mode,offerKey=0){
 let q;try{q=E.purchaseQuote(state,{model:id,mode,offer:offerKey});}catch(e){toast(e.message);return;}const m=q.m,label=q.offer?'购买二手':mode==='lease'?'租赁':'购买全新';
 showModal(`${label} ${E.modelName(m)}`,`<form id="purchase-form" data-model="${id}" data-mode="${mode}" data-offer="${offerKey}"><p class="purchase-summary">${q.delivery} 周交付 · ${q.offer?`${q.offer.age/52} 年机龄 / 状态 ${q.offer.condition}%`:'全新飞机'}${m.fictional?' · 虚拟飞机':''}</p><div class="purchase-fields"><label class="field">${mode==='lease'?'租赁':'采购'}数量（架）<input id="purchase-quantity" name="quantity" type="number" min="1" max="1000" step="1" inputmode="numeric" value="1"></label>${mode==='lease'?`<label class="field">出租方<select id="lease-lessor" data-model="${id}">${E.LESSORS.map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select></label>`:''}</div><div id="purchase-quote"></div><details class="purchase-details"><summary>交付与配置说明</summary><p>每架默认经济舱 ${m.seats} 席。交付前可分别调整舱位，新增座位需补交服务配置差额。${q.offer?'批量二手机使用所选档位的机龄、状态与报价。':''}${mode==='lease'?'每架飞机独立签订租约，交付后按周计租。':'自有飞机无租金，仍需支付机组、维护及运营费用。'}</p>${mode==='lease'?`<p id="lease-terms">${leaseTerms(m,E.LESSORS[0])}</p>`:''}</details><div class="form-actions"><button type="button" class="btn" data-action="closeModal">再考虑一下</button><button class="btn primary" type="submit" id="purchase-submit">确认${label}</button></div></form>`,'确认后按数量一次扣款，每架飞机独立进入机队');$('.modal').classList.add('purchase-modal');purchaseQuote();
}
function purchaseQuote(){const f=$('#purchase-form');if(!f)return;let q,error='';try{q=E.purchaseQuote(state,{model:f.dataset.model,mode:f.dataset.mode,offer:+f.dataset.offer,quantity:Number(f.elements.quantity.value)});}catch(e){error=e.message;}
 const l=f.querySelector('#lease-lessor')?.value,m=q?.m;$('#purchase-submit').disabled=!!error||q.total>state.cash;
 $('#purchase-quote').innerHTML=error?`<p class="notice" role="status">${esc(error)}</p>`:`<div class="quote"><div><small>单架${f.dataset.mode==='lease'?'押金':'飞机款'}</small>${money(q.unit)}</div><div><small>单架服务配置</small>${money(q.fitout)}</div><div><small>${q.quantity} 架合计支付</small><strong>${money(q.total)}</strong></div><div><small>支付后现金</small><span class="${q.total>state.cash?'negative':''}">${money(state.cash-q.total)}</span></div>${f.dataset.mode==='lease'?`<div class="quote-note">交付后合计周租 ${money(m.lease*E.lessor(l).factor*q.quantity)}</div>`:''}</div>${q.total>state.cash?'<p class="notice" role="status">现金不足，请减少数量或先融资。</p>':''}`;
}

function routeCabins(from,to,page=0){
 cabinRoute={from,to,page};const ids=[...new Set(E.routeAssignments(state,{from,to}).map(r=>r.plane))],planes=ids.map(id=>state.fleet.find(p=>p.id===id)).filter(Boolean),size=layoutMode()==='wide'?3:1,count=Math.max(1,Math.ceil(planes.length/size));page=Math.max(0,Math.min(page,count-1));
 showModal(`${from} ⇄ ${to} · 舱位管理`,`<p class="cabin-route-note">按执飞飞机配置座位。宽体可设三舱，窄体仅商务与经济；调整会同步影响该飞机执飞的其他航线。</p><div class="route-cabin-list">${planes.slice(page*size,(page+1)*size).map(p=>{const c=E.cabinOf(p),wide=E.cabinRules(E.model(p.model)).first,others=state.routes.filter(r=>r.plane===p.id&&!E.sameRoute(r,{from,to}));return `<article class="route-cabin-item"><h3>${esc(E.modelName(p.model))}</h3><p>B-YS${String(p.id).padStart(3,'0')} · ${wide?'宽体 · 可设三舱':'窄体 / 支线 · 两舱'}</p><div class="route-cabin-counts"><span>经济舱 <b>${c.economy}</b></span><span>商务舱 <b>${c.business}</b></span>${wide?`<span>头等舱 <b>${c.first}</b></span>`:''}</div><p>${others.length?'同时执飞 '+others.length+' 条其他航线':'目前仅执飞本航线'}</p>${button('调整这架飞机舱位','routeCabinEdit','seat',`data-id="${p.id}"`,'primary')}</article>`;}).join('')||'<div class="empty">当前航线没有已指派飞机，请先增派飞机。</div>'}</div><div class="form-actions"><div class="calendar-detail-pager">${button('上一架','routeCabinPage','',`data-page="${page-1}" ${page===0?'disabled':''}`)}<span>${planes.length} 架 · ${page+1}/${count}</span>${button('下一架','routeCabinPage','',`data-page="${page+1}" ${page===count-1?'disabled':''}`)}</div>${button('关闭','closeModal')}</div>`,'一条航线的所有执飞飞机，集中管理');
}
function cabinModal(id){const p=state.fleet.find(p=>p.id===id),m=E.model(p.model),c=E.cabinOf(p),rules=E.cabinRules(m);showModal(`${E.modelName(m)} · 客舱布局`,`<form id="cabin-form" data-id="${id}"><p class="cabin-route-note">${rules.first?'宽体机可设置头等、商务和经济舱。':'此机型可设置商务和经济舱。'} 当前配置应用于这架飞机的所有航线。</p><div class="cabin-presets">${[['standard','标准经济'],['dense','高密度经济'],['mixed','两舱布局'],...(rules.first?[['flagship','三舱旗舰']]:[])].map(([key,label])=>button(label,'cabinPreset','',`data-preset="${key}"`)).join('')}</div><div class="form-grid"><label class="field">经济舱座位<input type="number" name="economy" value="${c.economy}" min="0" max="${rules.max}" step="1" required></label><label class="field">商务舱座位<input type="number" name="business" value="${c.business}" min="0" max="${rules.max}" step="1" required></label>${rules.first?`<label class="field">头等舱座位<input type="number" name="first" value="${c.first}" min="0" max="${rules.max}" step="1" required></label>`:'<input type="hidden" name="first" value="0">'}<label class="field">经济舱座椅间距<select name="pitch">${[[28,'紧凑 · 28 英寸'],[30,'标准 · 30 英寸'],[33,'宽适 · 33 英寸']].map(([v,t])=>`<option value="${v}" ${v===c.pitch?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="cabin-tools">${button('用经济舱填满剩余空间','fillCabin')}</div><div id="cabin-quote" aria-live="polite"></div><div class="form-actions">${button('取消','closeModal')}<button class="btn primary" type="submit" id="save-cabin">应用客舱布局</button></div></form>`,`B-YS${String(id).padStart(3,'0')} · 在空间、票价与乘客体验之间取舍`,true);const actions=$('.modal-footer .form-actions');actions.insertAdjacentHTML('afterbegin',button('返回布局','cabinBack'));actions.insertAdjacentHTML('beforeend',button('查看费用与效果','cabinReview','arrow','','primary'));cabinQuote();cabinPanel(0);}
function cabinInput(){const f=$('#cabin-form');return Object.fromEntries(['economy','business','first','pitch'].map(k=>[k,Number(f.elements[k].value)]));}
function cabinQuote(){const f=$('#cabin-form');if(!f)return;const p=state.fleet.find(p=>p.id===+f.dataset.id),m=E.model(p.model),c=cabinInput(),cs=E.cabinStats(m,c);let error='';try{E.validateCabin(m,c);}catch(e){error=e.message;}const fee=E.cabinFee(p,c,state);$('#save-cabin').disabled=!!error||state.cash<fee;const assigned=state.routes.filter(r=>r.plane===p.id),sim={...state,fleet:state.fleet.map(x=>x.id===p.id?{...x,cabin:c}:x)},before=assigned.reduce((n,r)=>n+E.estimate(state,r).profit,0),after=error?0:assigned.reduce((n,r)=>n+E.estimate(sim,r).profit,0);$('#cabin-quote').innerHTML=`<div class="cabin-space"><div class="card-title"><strong>客舱空间分配</strong><small>${Math.round(cs.used/cs.budget*100)}% 已使用</small></div><div class="cabin-bar">${[['first',c.first*E.cabinRules(m).firstSpace,'头等舱'],['business',c.business*E.cabinRules(m).businessSpace,'商务舱'],['economy',c.economy*c.pitch,'经济舱']].map(([k,units,name])=>`<i class="${k}" style="width:${Math.max(0,Math.min(100,units/cs.budget*100))}%" title="${name} ${c[k]} 席"></i>`).join('')}</div><div class="cabin-legend">${E.cabinRules(m).first?`<span class="first">头等 ${c.first}</span>`:''}<span class="business">商务 ${c.business}</span><span class="economy">经济 ${c.economy}</span><span>空余 ${Math.max(0,Math.floor(cs.remaining/28))} 标准单位</span></div></div>${error?`<div class="notice">${error}</div>`:''}<div class="quote"><div><small>总座位</small>${cs.total} 席</div><div><small>客舱舒适度</small><strong class="${cs.comfort<m.comfort?'negative':'positive'}">${cs.comfort.toFixed(0)} / 100</strong></div><div><small>${p.delivery?'交付前配置差额':'本次改装费'}</small>${money(fee)}</div><div><small>经济舱体验</small>${cs.economyComfort.toFixed(0)} / 100</div><div><small>现有航线周贡献变化</small>${error?'—':money(after-before,true)}</div><div><small>经济舱 / 商务舱${E.cabinRules(m).first?' / 头等舱':''}票价</small>1 × / 2.5 ×${E.cabinRules(m).first?' / 4.8 ×':''}</div><div class="quote-note">${E.cabinRules(m).first?'商务舱和头等舱':'商务舱'}有独立客流上限。高密度布局增加运力，也会降低经济舱体验、客流和每周口碑；加座不保证收入上涨。空间是游戏预算，并非适航认证座位图。${assigned.length?'':'当前无执飞航线，贡献变化为 0。'}${state.cash<fee?' 现金不足，无法改装。':''}改装费用立即扣除，新布局用于下次结算；本版本不另计停场时间。</div></div>`;}
function maintenanceModal(id){const p=state.fleet.find(p=>p.id===id),base=E.model(p.model).price*.007*E.ageFactor(p);showModal('安排飞机检修',`<p>检修期间，所执飞航班暂停。机龄会增加检修费用；检修完成恢复维护状态。</p><button class="choice" data-action="confirmMaintenance" data-id="${id}"><strong>外包检修 · ${money(base)}</strong><small>2 周停场 · 无自有机库要求</small></button>${(state.hangars||[]).map(h=>{const u=E.hangarUsage(state,h);return `<button class="choice" data-action="confirmMaintenance" data-id="${id}" data-hangar="${h.code}" ${u.free<1?'disabled':''}><strong>${E.ap(h.code).city}自有机库 · ${money(base*.6)}</strong><small>1 周停场 · ${h.delivery?'施工中':`空闲 ${u.free} / ${u.slots} 位`} · 调机费用已简化计入检修费</small></button>`}).join('')}<div class="form-actions">${button('管理我的机库','navigate','tool','data-target="hangar"')}</div>`,'维护成本、维修位占用与时间都进入经营结算。');}
function hangar(){const hs=state.hangars||[];return `${head('MAINTENANCE & ENGINEERING','让机队背后，也有自己的实力。','飞机维护状态降至 65% 时自动检修：优先自有机库，维修位不足转外包；资金不足则停飞等待。')}${stats([['自有机库',hs.length,'座','每个运营基地可建 1 座','building'],['已启用维修位',hs.filter(h=>!h.delivery).reduce((n,h)=>n+h.level*2,0),'位','每级增加 2 位，可持续扩建','tool'],['在手外部订单',hs.reduce((n,h)=>n+h.contracts.length,0),'单','每单占用 1 个维修位，持续 4 周','chart'],['上周机库净贡献',money((state.lastReport?.hangarRevenue||0)-(state.lastReport?.hangarCost||0),true),'人民币','扣材料人工和机库固定费用','wallet']])}<div class="page-grid">${state.hubs.map(base=>{const h=hs.find(h=>h.code===base.code),u=h?E.hangarUsage(state,h):null;return `<article class="panel padded"><div class="card-title"><h2>${E.ap(base.code).city} · ${base.code}</h2><span class="tag">${h?h.delivery?'建设中':'等级 '+h.level:'待建机库'}</span></div>${h?`<p class="subtitle" style="margin:15px 0">${h.delivery?`${h.delivery} 周后启用`:`自家检修 ${u.internal} 位 · 外部订单 ${u.external} 位 · 空闲 ${u.free} 位`}</p><div class="hangar-bays">${(h.delivery?[['','施工中',u.slots]]:[['internal','自家检修',u.internal],['external','外部订单',u.external],['','空闲',u.free]]).map(([cls,label,count])=>`<div class="${cls}">${ic('tool',20)}<span>${label} ${count} 位</span></div>`).join('')}</div><p class="subtitle">固定开支 ${money(h.level*.09)} / 周。自家检修费用低 40%，停场从 2 周缩短至 1 周。</p>${h.contracts.length?`<p class="subtitle">外部订单余期：${[1,2,3,4].map(n=>{const count=h.contracts.filter(c=>c.remaining===n).length;return count?count+' 单剩 '+n+' 周':'';}).filter(Boolean).join(' / ')}</p>`:''}<div class="card-bottom">${button('承接外部订单','hangarOrder','',`data-code="${h.code}" ${u.free<1?'disabled':''}`,'primary')}${button('扩建 '+money(h.level*12),'upgradeHangar','',`data-code="${h.code}" ${h.delivery?'disabled':''}`)}</div>`:`<p class="subtitle" style="margin:18px 0">投资 1,800 万，建设期 4 周，启用后拥有 2 个维修位。自动检修会优先使用空闲维修位。</p>${button('投资建造机库','buildHangar','',`data-code="${base.code}"`,'primary')}`}</article>`}).join('')}</div><div class="notice" style="margin-top:20px">外部订单：每周收入 42 万，材料人工 20 万，连续 4 周；机库每级另付 9 万固定费用。请为自家机队留出维修位。此处是经营模拟，未细化维修资质、机型工装与人员适航许可。</div>`;}
function financeAssets(kind){const eligible=state.fleet.filter(p=>p.mode==='buy'&&!p.delivery&&!p.maintenance&&!E.pledged(state,p.id));showModal(kind==='mortgage'?'以飞机资产支持下一轮增长':'售后回租 · 回笼现金保留运力',`${eligible.length?eligible.map(p=>{let q,error='';try{q=E.assetFinanceQuote(state,p,kind);}catch(e){error=e.message;}return `<button class="choice" data-action="assetFinanceQuote" data-id="${p.id}" data-kind="${kind}" ${error?'disabled':''}><strong>${E.modelName(p.model)} · B-YS${String(p.id).padStart(3,'0')}</strong><small>${error||`预计净到账 ${money(q.net)} · 资产估值 ${money(q.value)}`}</small></button>`}).join(''):'<div class="empty">当前没有可用的自有飞机。先在飞机市场购买全新或二手飞机，交付后即可使用资产融资。</div>'}<div class="form-actions">${button('前往飞机市场','market')}</div>`,'已抵押、待交付或正在检修的飞机暂不可使用。');}
function assetFinanceModal(id,kind){const p=state.fleet.find(p=>p.id===id);try{const q=E.assetFinanceQuote(state,p,kind);confirmModal(kind==='mortgage'?'确认飞机抵押贷款':'确认售后回租',kind==='mortgage'?`${E.modelName(p.model)}：借款 ${money(q.amount)}，手续费 ${money(q.fee)}，净到账 ${money(q.net)}。年利率 5.2%，104 周等额还本；每周还本金 ${money(q.principal)}，首周利息 ${money(q.interest)}，之后随本金递减。飞机保留运营，未还清前不可出售、回租或重复抵押。`:`出售 ${E.modelName(p.model)} 获得 ${money(q.amount)}，扣除租赁押金 ${money(q.fee)}，净到账 ${money(q.net)}。航线和舱位保留，所有权转移为租赁；之后每周租金 ${money(E.model(p.model).lease)}。`,'confirmAssetFinance',`data-id="${id}" data-kind="${kind}"`);}catch(e){toast(e.message);}}
function financingPanels(){return `<section class="panel padded" style="margin-top:20px"><h2>用飞机资产，撬动下一架飞机</h2><div class="settings-row"><div><strong>飞机抵押贷款 · 年利率 5.2%</strong><p>按飞机估值的 50% 融资，手续费 0.5%，104 周等额还本。保留飞机所有权和运营能力。</p></div>${button('选择抵押飞机','financeAssets','','data-kind="mortgage"','primary')}</div><div class="settings-row"><div><strong>售后回租 · 一次性回笼资金</strong><p>卖出自有飞机并继续租用，释放现金，后续增加租金；可用二手飞机或全新飞机。</p></div>${button('选择回租飞机','financeAssets','','data-kind="leaseback"')}</div>${(state.facilities||[]).map(l=>`<div class="settings-row"><div><strong>${state.fleet.find(p=>p.id===l.plane)?.model} 抵押借款</strong><p>剩余 ${money(l.balance)} · ${l.remaining} 周 · 下周本金 ${money(Math.min(l.balance,l.original/104))} + 利息 ${money(l.balance*.052/52)}</p></div>${button('提前还清','repayMortgage','',`data-id="${l.plane}"`)}</div>`).join('')}</section>`;}

let settlementKind='week',settlementTab='summary',settlementToken='',settlementItems=[],settlementPage=0;
function weeklyReport(tab='summary'){if(!state.lastReport){toast('经营一周后即可查看简报。');return;}settlementReport('week',tab);}
function settlementNews(){const a=settlementItems[settlementPage];if(!a)return '<p class="settlement-note">本次没有新的经营提醒。</p>';AIR_ADVISOR.present(state,a.key);save();return `<section class="settlement-news"><div class="card-title"><strong>${esc(a.title)}</strong><span>${settlementPage+1}/${settlementItems.length}</span></div><p>${esc(a.text)}</p><div class="settlement-news-actions">${button('上一条','settlementMessage','','data-delta="-1" '+(!settlementPage?'disabled':''))}${button('下一条','settlementMessage','','data-delta="1" '+(settlementPage>=settlementItems.length-1?'disabled':''))}${button('查看详情','settlementOpen')}</div></section>`;}
function settlementReport(kind,tab='summary'){
 settlementKind=kind;settlementTab=tab;const batch=kind==='batch',r=batch?state.simulation:state.lastReport;if(!r)return;
 const token=kind+':'+(batch?r.startWeek+':'+r.completed:r.week);if(token!==settlementToken&&!simulationRunning){settlementToken=token;settlementItems=AIR_ADVISOR.fresh(state);settlementPage=0;retainAdvice(settlementItems);}
 const active=batch&&E.simulationActive(state),change=batch?(Number.isFinite(r.startRep)&&Number.isFinite(r.endRep)?r.endRep-r.startRep:null):(r.reputation?r.reputation.after-r.reputation.before:null),status=batch?(simulationRunning?'正在结算':r.status==='complete'?'模拟完成':state.pending?'等待决策':r.status==='cancelled'?'模拟已结束':'模拟暂停'):'经营简报';
 const tabs=`<nav class="wizard-tabs settlement-tabs" aria-label="结算内容">${[['summary','概览'],['details','收支明细']].map(([id,label])=>button(label,'settlementTab','',`data-tab="${id}" aria-pressed="${tab===id}"`,tab===id?'primary':'')).join('')}</nav>`;
 let body=simulationRunning?'':tabs;
 if(batch)body+=`<div class="batch-progress"><span style="width:${r.completed/r.target*100}%"></span></div><p class="batch-status">${simulationRunning?`已结算 ${r.completed} / ${r.target} 周，可随时暂停。`:state.pending?'待决策：'+esc(state.pending.title):active?`剩余 ${r.target-r.completed} 周。`:'本次结果已保存。'}</p>`;
 if(tab==='summary')body+=`<div class="quote settlement-metrics"><div><small>${batch?'累计':'本周'}净利润</small><strong class="${r.profit>=0?'positive':'negative'}">${money(r.profit,true)}</strong></div><div><small>当前现金</small>${money(state.cash)}</div><div><small>承运旅客</small>${r.pax.toLocaleString()} 人次</div><div><small>${batch?'期间':'本周'}口碑变化</small>${change===null?'—':(change>=0?'+':'')+change.toFixed(2)}</div></div><p class="settlement-note">${r.flights} 班已执行 · 自动保障与检修支出已计入利润${saveError?' · ⚠ 尚未自动保存，请导出进度':''}</p>${!batch&&state.pending?`<p class="settlement-note">待决策：${esc(state.pending.title)}</p>`:''}${simulationRunning?'':settlementNews()}`;
 else body+=batch?`<div class="quote"><div><small>累计收入</small>${money(r.revenue)}</div><div><small>累计成本</small>${money(r.cost)}</div><div><small>现金变化</small>${money((active?state.cash:r.endCash??state.cash)-r.startCash,true)}</div></div><p>现金变化含采购、融资与事件支出，净利润只统计已结算经营周。</p><div class="batch-weekly">${r.rows.map(w=>`<div><span>第 ${w.week} 周</span><span>${w.pax.toLocaleString()} 人次</span><strong>${money(w.profit,true)}</strong></div>`).join('')}</div>`:`${reportLines(r)}${r.network?`<p>转机行程 ${r.network.transferPax} 次 · 联程收入 ${money(r.network.transferRevenue)}</p>`:''}${r.reputation?`<p>口碑：服务体验 ${r.reputation.earned.toFixed(2)} · 延误与衔接 ${r.reputation.disruptions.toFixed(2)} · 停航 ${r.reputation.cancellations.toFixed(2)}</p>`:''}${r.disruption?.delayedLegs?button('延误与旅客保障','delayReport','shield'):''}<p>${(r.events||[]).map(esc).join(' · ')}</p>`;
 const actions=simulationRunning?button('暂停模拟','pauseBatch','','','primary'):button('返回经营','closeModal')+(active?button('结束模拟','cancelBatch'):'')+(state.pending?button('处理经营事件','story','arrow','','primary'):active?button(`继续剩余 ${r.target-r.completed} 周`,'resumeBatch','arrow','','primary'):button('经营下一周','advance','arrow',state.bankrupt?'disabled':'','primary'));
 showModal(batch?`${status} · ${r.completed}/${r.target} 周`:`第 ${r.week} 周 · ${status}`,body+`<div class="form-actions">${actions}</div>`,batch?`${dateText(r.startDate)} → ${dateText(r.endDate||state.date)}`:dateText(r.date),true);
}
function story(){if(!state.pending){toast('当前没有待处理的董事会事件。');return;}$('#toast').classList.remove('show');showModal(esc(state.pending.title),`<p>${esc(state.pending.text)}</p>${state.pending.choices.map((c,i)=>`<button class="choice" data-action="choice" data-index="${i}"><strong>${esc(c.label)}</strong><small>${c.cash<0?'支出 '+money(-c.cash):'无额外现金支出'} · 口碑 ${c.rep>0?'+':''}${c.rep||0}${c.event?` · ${c.event.closed?'相关航线停飞':`相关需求 ×${(c.event.demand||1).toFixed(2)}`}，持续 ${c.duration} 周`:''}</small><small>${esc(c.result)}</small></button>`).join('')}`,esc(state.pending.tag));}
function setupAirportOptions(province,selected){return D.airports.filter(a=>a.region==='CN'&&a.province===province).map(a=>`<option value="${a.code}" ${a.code===selected?'selected':''}>${airportOptionLabel(a)}</option>`).join('');}
function newGame(first=false,stage=0){setupFirst=first;setupStage=stage;const steps=`<div class="onboard-progress">${['一个梦想','你的航司','准备起飞'].map((t,i)=>`<span class="${i===stage?'current':''}">${String(i+1).padStart(2,'0')} ${t}</span>`).join('')}</div>`;let body='';if(stage===0)body=`<div class="dream-photo"><span>THE JOURNEY STARTS WITH YOU</span></div><div class="dream-copy"><h3>把望向天空的那一眼，<br>变成自己的航线图。</h3><p>从第一次在舷窗边看见云海，到想让一架写着自己航司名字的飞机起飞。这里，留给每一个有蓝天梦的人。</p><p>选择一座出发的城市。从第一条航线开始，把可靠、温暖的飞行带到更远的地方。</p></div><div class="form-actions">${button('开始我的航空故事','onboardNext','arrow','','primary')}</div>`;else if(stage===1)body=`<form id="identity-form"><p class="setup-intro">给梦想一个名字，也给它一座起飞的机场。</p><div class="form-grid"><label class="field full">航空公司名称<input name="name" maxlength="16" value="${esc(setupDraft.name)}" required placeholder="为你的航空公司取名"></label><label class="field">基地省份 / 直辖市<select name="province">${D.provinces.map(province=>`<option value="${province}" ${province===E.ap(setupDraft.base).province?'selected':''}>${province}</option>`).join('')}</select></label><label class="field">城市 / 基地机场<select name="base">${setupAirportOptions(E.ap(setupDraft.base).province,setupDraft.base)}</select></label></div><div class="setup-capital"><span>创始资本</span><strong>2,000 <small>万元</small></strong><p>另有全新自有 Airbus A320neo、Boeing 737-8（MAX 8）各一架，已交付，无租金、无贷款。</p></div><div class="form-actions">${button('上一步','onboardBack')}<button type="submit" class="btn primary">查看首航计划 ${ic('arrow',14)}</button></div></form>`;else {const preview=E.initial(setupDraft);body=`<form id="new-game-form"><input name="name" type="hidden" value="${esc(setupDraft.name)}"><input name="base" type="hidden" value="${setupDraft.base}"><div class="boarding-pass"><div><small>首航准备 · READY FOR DEPARTURE</small><h3>${esc(setupDraft.name)}</h3><p>${E.ap(setupDraft.base).city}基地 · ${setupDraft.base}</p></div><strong>${setupDraft.base}</strong></div><div class="launch-plan"><p><b>01</b> 接收两架全新自有飞机：Airbus A320neo 与 Boeing 737-8，各自安排一条首航航线。</p><p><b>02</b> 首航 ${preview.routes.map(r=>E.ap(r.to).city).join('、')}，先熟悉航线与旅客服务。</p><p><b>03</b> 查看经营周报，用下一周的收入规划更远的目的地。</p></div>${first?'':'<label class="checkboxline"><input type="checkbox" required>我确认重新开始，替换当前浏览器中的经营进度。</label>'}<div class="form-actions">${button('返回修改','onboardBack')}<button type="submit" class="btn primary">创立我的航空公司 ${ic('arrow',14)}</button></div></form>`;}showModal(stage===0?'致每一个有蓝天梦的人':stage===1?'从这里，写下航司的名字。':'你的第一张航线图，已准备好。',steps+body,'打造全球最佳航司 · 创始人登机指引',stage===0);}

function guide(){showModal('从第一条航线，到世界最佳航司。',`<div class="help-steps">${[['经营一周','点击右上角经营下一周。所有航线统一结算，报告展示完整收支；每四周会有一项需要决策的事件。'],['为飞机安排合适航线','选择出发基地、目的地、执飞机型与班次。每周最多飞行 100 小时；全天可排班，含经停和周转的占用不能超过一周 168 小时。'],['分清贡献和利润','航线贡献只扣飞行相关成本；公司净利润还会扣飞机租金、薪酬、总部费用和贷款利息。'],['在增长中留出余量','租赁飞机 2 周交付，购买 6 周交付。飞机维护低于 55 自动停飞，两周检修后恢复。不要把现金全部花完。'],['提升服务并走向国际','提高口碑到 60，并拥有 3 架已交付飞机，即可申请国际资质。关注节假日、世界杯与奥运客流。'],['冲击全球第一','机队达到 100 架、覆盖 100 座城市后规模分封顶。通过实际服务积累口碑与服务得分，保持可靠性和连续盈利，冲击全球第一。']].map(([t,d])=>`<div><section><h4>${t}</h4><p>${d}</p></section></div>`).join('')}</div><div class="form-actions">${button('开始我的下一程','closeModal','arrow','','primary')}</div>`,'这是每周推进的经营模拟，所有选择都会进入经营结算。');}
function loan(){bankAmountModal('loan');}
function bankAmountModal(kind){const borrowing=kind==='loan',limit=E.bankAvailable(state,kind);showModal(borrowing?'申请银行贷款':'偿还银行贷款',`<form id="bank-amount-form" data-kind="${kind}"><p>${borrowing?'年利率 6.5%，按周计息。剩余可借额度':'可偿还金额（不超过现金与银行欠款）'}：<strong>${money(limit)}</strong></p><label class="field">金额（万元）<input name="amount" type="number" min="1" max="${Math.round(limit*100)}" step="1" value="${Math.min(5000,Math.round(limit*100))}" required></label><div class="bank-presets">${[5000,10000,50000].filter(n=>n<=Math.round(limit*100)).map(n=>button(n.toLocaleString()+' 万','bankPreset','',`data-value="${n}"`)).join('')}${button(borrowing?'填入全部额度':'填入全部可还','bankPreset','',`data-value="${Math.round(limit*100)}" ${limit<=0?'disabled':''}`)}</div><p class="muted">填写金额后确认，一次完成。${borrowing?'金额上限仍由当前资产授信决定。':'这里只偿还银行贷款；飞机抵押贷款在原有资产融资入口管理。'}</p><div class="form-actions">${button('取消','closeModal')}<button type="submit" class="btn primary" ${limit<=0?'disabled':''}>${borrowing?'确认借款':'确认还款'}</button></div></form>`,'支持自定义金额 · 最小单位 1 万元');}

function confirmModal(title,text,action,extra,cls='primary'){showModal(title,`<p>${text}</p><div class="form-actions">${button('取消','closeModal')}${button('确认',''+action,'',extra,cls)}</div>`);}
document.addEventListener('toggle',ev=>{if(ev.target.id==='catalog-filters')catalogFiltersOpen=ev.target.open;},true);
// A multi-click gesture must not activate a control revealed by its first click.
document.addEventListener('click',ev=>{if(ev.detail>1&&ev.target.closest('button,[data-action],[data-view],.modal-backdrop')){ev.preventDefault();ev.stopImmediatePropagation();}},true);
document.addEventListener('click',ev=>{if(panoramaDragged&&ev.target.closest('.world-map')){panoramaDragged=false;return;}if(ev.target.classList.contains('modal-backdrop')){closeModal();return;}const el=ev.target.closest('[data-view],[data-action]');if(!el)return;if(el.dataset.view){setView(el.dataset.view);return;}let a=el.dataset.action,id=+el.dataset.id;if(simulationRunning&&!['pauseBatch','closeModal'].includes(a))return;switch(a){case 'operationPage':operationsModal(null,operationPage+Number(el.dataset.delta));break;case 'retirement':retirementModal(id);break;case 'replaceRetired':case 'deferRetirement':resolveRetirement(a,id);break;case 'calendarFlight':calendarFlightDetail(+el.dataset.dayIndex,+el.dataset.group);break;case 'calendarDetailPrev':calendarFlightDetail(null,null,calendarDetailPage-1);break;case 'calendarDetailNext':calendarFlightDetail(null,null,calendarDetailPage+1);break;case 'routeCabinEdit':cabinModal(id);break;case 'routeCabins':routeCabins(el.dataset.from,el.dataset.to);break;case 'routeCabinPage':routeCabins(cabinRoute.from,cabinRoute.to,+el.dataset.page);break;case 'chooseScheduleRoute':chooseScheduleRoute();break;case 'applyScheduleRoute':scheduleFrom=$('#route-schedule-from').value;scheduleTo=$('#route-schedule-to').value;scheduleDirection='out';scheduleDay='all';pages.routeTimetable=0;closeModal();render();break;case 'scheduleMode':scheduleMode=el.dataset.mode;render();break;case 'scheduleDirection':scheduleDirection=el.dataset.direction;pages.routeTimetable=0;render();break;case 'routeSchedule':scheduleMode='route';scheduleFrom=el.dataset.from;scheduleTo=el.dataset.to;scheduleDay='all';scheduleDirection='out';pages.routeTimetable=0;setView('schedule');break;case 'autoRouteSchedule':confirmModal('航线与飞机联动排班',`${scheduleFrom} ⇄ ${scheduleTo} 的执飞飞机将共同重排，包括这些飞机的其他在营航线。将解除这些航线的手动时刻；班次数量、配机与票价不变。同方向至少间隔 1 小时，班次少时拉开间隔。排不下时不保存任何改动。`,'confirmAutoRouteSchedule','');break;case 'confirmAutoRouteSchedule':act('autoRouteSchedule',{from:scheduleFrom,to:scheduleTo},'航线与飞机已联动排班');break;case 'settlementTab':settlementReport(settlementKind,el.dataset.tab);break;case 'settlementMessage':settlementPage=Math.max(0,Math.min(settlementItems.length-1,settlementPage+Number(el.dataset.delta)));settlementReport(settlementKind,'summary');break;case 'settlementOpen':{const item=settlementItems[settlementPage];if(item){advisorItems=[item];advisorPage=0;advisorReturn=settlementKind==='batch'?'batch':'report';advisorModal(false);}break;}case 'retrySave':{const loaded=saveStore.load();state=loaded.state;resetLoadedUI();needsSetup=loaded.empty;saveError=!!loaded.error;saveIssue=loaded.error||'';render();if(needsSetup)newGame(true);break;}case 'exportOriginal':try{const raw=saveStore.raw();if(!raw)throw Error('当前没有可导出的原始存档。');downloadSave(raw,'航司-原始存档-保留.json');}catch(e){toast(e.message);}break;case 'restoreSave':restoreSave(el.dataset.backup);break;case 'confirmRestore':try{const restored=saveStore.restore(el.dataset.backup);state=restored;resetLoadedUI();saveError=false;needsSetup=false;closeModal();view='overview';render();toast('存档已恢复，可从第 '+state.week+' 周继续。');}catch(e){toast(e.message);}break;case 'traffic':trafficPanel('airlines',0);break;case 'trafficTab':trafficQuery='';trafficPanel(el.dataset.tab,0);break;case 'trafficPage':trafficPanel(trafficTab,trafficPage+Number(el.dataset.delta),trafficSize);break;case 'trafficMine':trafficQuery='';trafficMine=!trafficMine;trafficPanel('airports',0);break;case 'trafficAirport':trafficAirport(el.dataset.code);break;case 'trafficContest':trafficContest(el.dataset.key);break;case 'contestPage':trafficContest(contestKey,contestPage+Number(el.dataset.delta));break;case 'trafficRoutes':trafficRoutes(el.dataset.key);break;case 'routeGroup':routeGroup(el.dataset.from,el.dataset.to);break;case 'routeGroupPage':routeGroup(routeGroupFrom,routeGroupTo,routeGroupPage+Number(el.dataset.delta));break;case 'addRoutePlane':routeModal(null,el.dataset.to,null,el.dataset.from);break;case 'network':networkPanel('summary',0);break;case 'networkSection':networkPanel(el.dataset.section,0);break;case 'networkPage':networkPanel(networkSection,networkPage+Number(el.dataset.delta));break;case 'networkPlan':routeModal(null,el.dataset.to,+el.dataset.plane,el.dataset.from);$('#route-form').elements.freq.value=3;routeQuote();break;case 'planeRoutes':planeRoutes(id);break;case 'planeRoutePage':planeRoutes(managedPlane,managedRoutePage+Number(el.dataset.delta));break;case 'delayPolicy':delayPolicyModal();break;case 'delayReport':delayPanel(+el.dataset.page||0);break;case 'leaseDetail':leaseDetail(id);break;case 'advisor':advisorModal();break;case 'advisorPrev':advisorPage--;advisorModal(false);break;case 'advisorNext':advisorPage++;advisorModal(false);break;case 'advisorOpen':openAdvisorSuggestion();break;case 'advisorReport':advisorReturn==='batch'?batchReport():weeklyReport();break;case 'panorama':panorama();break;case 'mapZoom':zoomPanorama(+el.dataset.factor);break;case 'mapFit':panoramaView={x:0,y:0,w:1000,h:450};applyPanorama();break;case 'mapBase':focusMapAirport(state.base);break;case 'quickAdvance':quickAdvance();break;case 'batchPanel':batchPanel();break;case 'batchReport':batchReport();break;case 'startBatch':quickAdvance(+el.dataset.weeks);break;case 'resumeBatch':runSimulation();break;case 'pauseBatch':stopSimulation();batchReport();break;case 'cancelBatch':stopSimulation();E.cancelSimulation(state);save();render();batchReport();break;case 'routeStage':setRouteStage(+el.dataset.stage);break;case 'routeBack':setRouteStage(routeStage-1);break;case 'routeNext':setRouteStage(routeStage+1);break;case 'cabinReview':cabinPanel(1);break;case 'cabinBack':cabinPanel(0);break;case 'blueDream':blueDream();break;case 'onboardNext':newGame(setupFirst,setupStage+1);break;case 'onboardBack':{const f=$('#identity-form');if(f)setupDraft=Object.fromEntries(new FormData(f));newGame(setupFirst,Math.max(0,setupStage-1));break;}case 'modelDetail':modelDetail(el.dataset.model);break;case 'page':pages[el.dataset.key]=(pages[el.dataset.key]||0)+Number(el.dataset.delta);render();break;case 'dashboardTab':dashboardTab=el.dataset.tab;render();break;case 'networkTab':networkTab=el.dataset.tab;render();break;case 'chooseStop':{const f=$('#route-form'),airport=E.ap(el.dataset.code);f.elements.viaCountry.value=airport.country;f.elements.via.innerHTML=cityOptions(airport.country,airport.code);f.elements.stopMinutes.value=90;routeQuote();break;}case 'airlineDetail':airlineDetail(el.dataset.code);break;case 'airlineDetailTab':airlineDetail(el.dataset.code,el.dataset.tab);break;case 'hub':hubModal();break;case 'rebase':rebaseModal(id);break;case 'planMarket':routeModal(null,el.dataset.to,null,el.dataset.from);break;case 'manualSchedule':manualSchedule(id);break;case 'autoSchedule':confirmModal('飞机与航线联动排班','这架飞机及同航线的其他执飞飞机，将一起重排全部在营航线并解除手动时刻。同方向至少间隔 1 小时，班次少时拉开间隔；保持原班次数量，排不下则保留原计划。','confirmAutoSchedule',`data-id="${id}"`);break;case 'confirmAutoSchedule':act('autoSchedule',{id},'周计划已自动生成');break;case 'usedOffers':usedMarket(el.dataset.model);break;case 'cabin':cabinRoute=null;cabinModal(id);break;case 'cabinPreset':{const f=$('#cabin-form'),p=state.fleet.find(p=>p.id===+f.dataset.id),c=E.cabinPreset(E.model(p.model),el.dataset.preset);Object.entries(c).forEach(([k,v])=>f.elements[k].value=v);cabinQuote();break;}case 'fillCabin':{const f=$('#cabin-form'),p=state.fleet.find(p=>p.id===+f.dataset.id);f.elements.economy.value=E.cabinStats(E.model(p.model),cabinInput()).maxEconomy;cabinQuote();break;}case 'buildHangar':confirmModal('建造自有机库','投入 1,800 万，4 周后启用 2 个维修位。启用后每周固定支出 9 万。','confirmBuildHangar',`data-code="${el.dataset.code}"`);break;case 'confirmBuildHangar':act('buildHangar',{code:el.dataset.code},'机库已开工');break;case 'upgradeHangar':{const h=state.hangars.find(h=>h.code===el.dataset.code);confirmModal('扩建机库维修能力',`投入 ${money(h.level*12)}，新增 2 个维修位，每周固定费用增加 9 万。`,'confirmUpgradeHangar',`data-code="${h.code}"`);break;}case 'confirmUpgradeHangar':act('upgradeHangar',{code:el.dataset.code},'机库已扩建');break;case 'hangarOrder':confirmModal('承接四周例行检修订单','一个维修位将连续占用四周。每周收入 42 万，材料人工 20 万；另承担机库固定开支。','confirmHangarOrder',`data-code="${el.dataset.code}"`);break;case 'confirmHangarOrder':act('hangarContract',{code:el.dataset.code},'外部维修订单已签订');break;case 'financeAssets':financeAssets(el.dataset.kind);break;case 'assetFinanceQuote':assetFinanceModal(id,el.dataset.kind);break;case 'confirmAssetFinance':act(el.dataset.kind,{id},'资产融资已完成');break;case 'repayMortgage':{const l=state.facilities.find(l=>l.plane===id);confirmModal('提前还清抵押借款',`支付 ${money(l.balance)}，解除飞机抵押。`,'confirmRepayMortgage',`data-id="${id}"`);break;}case 'confirmRepayMortgage':act('repayMortgage',{id},'抵押贷款已还清');break;case 'navigate':setView(el.dataset.target);break;case 'closeModal':closeModal();break;case 'guide':guide();break;case 'advance':advanceDirect();break;case 'report':weeklyReport();break;case 'map':mapMode=el.dataset.mode;panoramaView={x:0,y:0,w:1000,h:450};render();break;case 'newRoute':routeModal(null,null,+el.dataset.plane||null);break;case 'editRoute':routeModal(id);break;case 'airport':if($('.panorama-modal')){focusMapAirport(el.dataset.code);break;}if(el.dataset.code===state.base)toast('这是你的主基地。在航线网络中规划新目的地。');else routeModal(null,el.dataset.code);break;case 'toggle':act('toggle',{id},'航线运营状态已更新');break;case 'closeRoute':confirmModal('关闭这条航线？','飞机将被保留，开航费用不会退还；可以重新规划其他目的地。','confirmClose',`data-id="${id}"`,'danger');break;case 'confirmClose':act('close',{id},'航线已关闭，飞机可重新调配');break;case 'market':setView('market');break;case 'fleetFilter':fleetFilter=el.dataset.filter;pages.fleet=0;render();break;case 'purchaseChannel':purchaseChannel=el.dataset.channel;render();break;case 'marketFilter':marketFilter=el.dataset.filter;render();break;case 'rankFilter':rankFilter=el.dataset.filter;pages.ranking=0;render();break;case 'acquire':acquisition(el.dataset.model,el.dataset.mode,+el.dataset.offer||0);break;case 'confirmAcquire':act('buy',{model:el.dataset.model,mode:el.dataset.mode,offer:+el.dataset.offer||0,lessor:$('#lease-lessor')?.value},'已签订飞机合同，交付进度可在机队中查看');break;case 'maintain':maintenanceModal(id);break;case 'confirmMaintenance':act('maintenance',{id,hangar:el.dataset.hangar},'飞机已进入检修计划');break;case 'dispose':{let p=state.fleet.find(x=>x.id===id);confirmModal(p.mode==='lease'?'退还租赁飞机':'出售自有飞机','所有相关航线需先关闭或改派。退租返还 80% 押金；出售按机龄与维护状态折价。','confirmDispose',`data-id="${id}"`,'danger');break;}case 'confirmDispose':act('sell',{id},'飞机已处置，资金已到账');break;case 'serviceUpgrade':{let k=el.dataset.key;confirmModal('升级'+SERVICE.find(x=>x[0]===k)[2],`本次投入 ${money(E.serviceUpgradeCost(state,k))}，为 ${state.fleet.length} 架飞机统一升级一级（含待交付订单），并增加未来运营成本。新购或租入飞机会另收补齐公司标准的配置费。`,'confirmService',`data-key="${k}"`);break;}case 'confirmService':act('service',{key:el.dataset.key},'服务升级完成');break;case 'story':story();break;case 'choice':resolveOperatingChoice(+el.dataset.index);break;case 'newGame':newGame();break;case 'pricingPolicy':act('pricingPolicy',{enabled:!state.autoPricing},state.autoPricing?'已改为手动定价':'自动定价已启用，下周按策略调整');break;case 'loan':loan();break;case 'confirmLoan':act('loan',{amount:+el.dataset.amount},'贷款已到账');break;case 'repay':bankAmountModal('repay');break;case 'bankPreset':$('#bank-amount-form').elements.amount.value=el.dataset.value;break;case 'confirmRepay':act('repay',{amount:50},'贷款已偿还');break;case 'hedge':confirmModal('锁定未来十二周航油价格','支付 200 万元，抵消燃油价格冲击；绕飞耗油变化仍会发生。','confirmHedge','');break;case 'confirmHedge':act('hedge',{},'航油保价已生效');break;case 'license':act('license',{},'国际及地区资质已提交审批');break;case 'expandHub':confirmModal('扩建基地时刻',`投入 ${money(state.hubs.find(h=>h.code===el.dataset.code).level*18)}，每周增加 180 个单程时刻。`,'confirmExpand',`data-code="${el.dataset.code}"`);break;case 'confirmExpand':act('expand',{code:el.dataset.code},'基地扩建已完成');break;case 'marketing':act('marketing',{},'四周品牌推广已启动');break;case 'export':downloadSave(JSON.stringify(state,null,2),`打造全球最佳航司-存档-W${state.week}.json`);toast('存档已导出');break;case 'import':confirmModal('导入会替换当前进度','先验证旧存档并补齐新字段，再保留当前进度的备份。接下来选择本游戏导出的 JSON 文件。','selectImport','');break;case 'selectImport':closeModal();$('#import-file').click();break;}});
document.addEventListener('change',ev=>{if(ev.target.id==='calendar-day'){calendarGo(+ev.target.value);return;}if(ev.target.id==='route-schedule-from'){scheduleDestinationOptions($('#route-schedule-to').value);return;}if(ev.target.closest('#identity-form')&&ev.target.name==='province'){const f=$('#identity-form');f.elements.base.innerHTML=setupAirportOptions(ev.target.value,f.elements.base.value);return;}if(ev.target.id==='lease-lessor'){$('#lease-terms').textContent=leaseTerms(E.model(ev.target.dataset.model),E.lessor(ev.target.value));purchaseQuote();return;}if(ev.target.id==='panorama-airport'){focusMapAirport(ev.target.value);return;}if(ev.target.id==='category-filter'){marketFilter=ev.target.value;pages.market=0;render();return;}if(ev.target.id==='channel-filter'){purchaseChannel=ev.target.value;pages.market=0;render();return;}if(ev.target.id==='mobile-view'){setView(ev.target.value);return;}if(ev.target.id==='insight-base'){insightBase=ev.target.value;pages.insights=0;render();}if(ev.target.id==='insight-country'){insightCountry=ev.target.value;pages.insights=0;render();}if(ev.target.id==='insight-sort'){insightSort=ev.target.value;pages.insights=0;render();}if(['schedule-from','schedule-to','schedule-day'].includes(ev.target.id)){if(ev.target.id==='schedule-from')scheduleFrom=ev.target.value;if(ev.target.id==='schedule-to')scheduleTo=ev.target.value;if(ev.target.id==='schedule-day')scheduleDay=ev.target.value;pages.routeTimetable=0;render();return;}if(ev.target.id==='schedule-plane'){schedulePlane=+ev.target.value;render();}if(ev.target.closest('#hub-form')&&ev.target.name==='country')$('#hub-form').elements.code.innerHTML=cityOptions(ev.target.value,null,true);if(ev.target.closest('#route-form')){const f=$('#route-form');if(ev.target.name==='country')f.elements.to.innerHTML=routeCityOptions(ev.target.value,f.elements.from.value);if(ev.target.name==='viaCountry'){f.elements.via.innerHTML=ev.target.value?cityOptions(ev.target.value,ev.target.value==='美国'?'LAX':null):'<option value="">不经停</option>';}if(ev.target.name==='from'){f.elements.plane.innerHTML=planeOptions(ev.target.value);f.elements.to.innerHTML=routeCityOptions(f.elements.country.value,ev.target.value,f.elements.to.value);}if(['country','to','from'].includes(ev.target.name))selectAdditionalPlane();}if(ev.target.closest('#schedule-form'))scheduleQuote();if(ev.target.id==='maker-filter'){makerFilter=ev.target.value;pages.market=0;render();}if(ev.target.closest('#route-form'))routeQuote();if(ev.target.closest('#cabin-form'))cabinQuote();});document.addEventListener('input',ev=>{if(ev.target.id==='purchase-quantity'){purchaseQuote();return;}if(ev.target.closest('#schedule-form'))scheduleQuote();if(ev.target.closest('#route-form'))routeQuote();if(ev.target.closest('#cabin-form'))cabinQuote();if(ev.target.id==='rank-search'){rankQuery=ev.target.value;pages.ranking=0;$('#ranking-table').innerHTML=rankingTable();}});
document.addEventListener('submit',ev=>{ev.preventDefault();let form=ev.target,data=Object.fromEntries(new FormData(form));if(form.id==='bank-amount-form'){act(form.dataset.kind,{amount:Number(data.amount)/100},form.dataset.kind==='loan'?'贷款已到账':'贷款已偿还');return;}if(form.id==='delay-policy-form'){act('delayPolicy',data,'延误保障策略已保存，下周生效');return;}if(form.id==='identity-form'){setupDraft={name:(data.name||'').trim(),base:data.base};if(!setupDraft.name){toast('请给你的航司取一个名字。');return;}newGame(setupFirst,2);return;}if(form.id==='schedule-form')act('schedule',{id:+form.dataset.id,schedule:scheduleInput()},'航班时刻已锁定');if(form.id==='rebase-form')act('rebase',{id:+form.dataset.id,code:data.code},'飞机调动已安排');if(form.id==='cabin-form'){const returnRoute=cabinRoute;if(act('cabin',{...cabinInput(),id:+form.dataset.id},'客舱布局已保存，下次结算生效')&&returnRoute)routeCabins(returnRoute.from,returnRoute.to,returnRoute.page);}if(form.id==='route-form')act(form.dataset.id?'editRoute':'route',{...data,id:+form.dataset.id},'航线计划已保存，下周开始按新计划运营');if(form.id==='new-game-form'){try{const next=E.migrateSave(E.initial(data));saveStore.write(next);state=next;resetLoadedUI();saveError=false;}catch(error){toast(error.message);return;}needsSetup=false;closeModal();view='overview';render();toast('你的航空公司已经成立。下一站，世界。');}if(form.id==='hub-form')act('hub',{code:data.code},'新运营基地已设立');});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.destination')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const nodes=[...$('.modal').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a')].filter(n=>!n.closest('[hidden]')&&n.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>32e6)throw Error('存档文件过大（上限 32 MB）。');const next=saveStore.importRaw(await file.text());state=next;resetLoadedUI();saveError=false;needsSetup=false;closeModal();view='overview';render();toast('旧进度已接续：第 '+state.week+' 周，机队、航线与资金保留。');}catch(err){toast(err.message||'无法读取这个存档，当前进度没有替换。');}finally{e.target.value='';}});
let resizeTimer,viewportNeedsRender=false;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{const mode=layoutMode();let changed=mode!==viewportMode;for(const [key,m] of Object.entries(pageMeta)){const next=pageSize(key,m.kind||'table',mode);if(next!==m.size){pages[key]=Math.floor((pages[key]||0)*m.size/next);m.size=next;changed=true;}}viewportMode=mode;resizeTrafficPanel();if(changed){if($('.modal'))viewportNeedsRender=true;else render();}else calendarRestore();},120);});
render();if(needsSetup)newGame(true);if(loadedSave.migrated)toast('已接续旧版经营进度，首次保存前会保留改版前备份。');

document.addEventListener('change',ev=>{if(ev.target.id==='calendar-day'){calendarGo(+ev.target.value);return;}if(ev.target.id==='network-base'){networkBase=ev.target.value;networkPanel('expand',0);}});

document.addEventListener('submit',ev=>{if(ev.target.id!=='traffic-search-form')return;ev.preventDefault();trafficQuery=ev.target.elements.query.value.trim();trafficPanel(trafficTab,0);});

document.addEventListener('submit',ev=>{const f=ev.target;if(f.id!=='purchase-form')return;ev.preventDefault();const quantity=Number(f.elements.quantity.value);act('buy',{model:f.dataset.model,mode:f.dataset.mode,offer:+f.dataset.offer,quantity,lessor:f.querySelector('#lease-lessor')?.value},`已订购 ${quantity} 架飞机，可在机队查看交付进度`);});
function simpleDelayPanel(d,page=0){const size=window.innerHeight<500?1:2,rows=d.journeys.filter(j=>j.delay>180),pages=1+Math.ceil(rows.length/size);page=Math.max(0,Math.min(page,pages-1));const body=page===0?`<div class="quote"><div><small>延误航段 / 准点率</small>${d.delayedLegs} / ${d.onTime.toFixed(1)}%</div><div><small>受影响旅客</small>${d.affectedPax} 人</div><div><small>自动改签 / 退款</small>${d.rebookedOwn+d.rebookedPartner} / ${d.refundedPax} 人次</div><div><small>联程受影响</small>${d.missedConnections} 人</div><div><small>保障后满意度</small>${d.satisfaction.toFixed(1)} / 100</div><div><small>口碑影响</small>${d.repDelta.toFixed(3)}</div></div><div class="report-lines">${[['退款减少收入',d.refunds],['赔付与食宿',d.compensation+d.care],['改签支出',d.rebooking],['运行支出',d.operations]].map(([label,n])=>`<div><span>${label}</span><span>−${money(n)}</span></div>`).join('')}<div class="total"><span>本周利润影响</span><strong>−${money(d.loss)}</strong></div></div>`:rows.slice((page-1)*size,page*size).map(j=>`<article class="delay-leg"><h3>${E.ap(j.from).city} ${j.from} ⇄ ${E.ap(j.to).city} ${j.to}</h3><p>${j.delayedFlights} 班 · 延误 ${j.delay} 分钟 · ${j.pax} 名旅客受影响</p><p>自动改签 ${j.handling.own+j.handling.partner} 人，退款 ${j.handling.refund} 人，等待 ${j.handling.waiting} 人。</p></article>`).join('');showModal(`第 ${d.week} 周 · 运行保障`,`${body}<p class="muted">按周随机与比例估算；同航路班次越密，替代能力越强。联程影响随航网规模增加，不逐班传播，不延续到下周。明细只列超过 3 小时的延误。</p><div class="form-actions">${button(page?'上一页':'关闭',page?'delayReport':'closeModal','','data-page="'+(page-1)+'"')}${button('保障策略','delayPolicy')}${page<pages-1?button('下一页','delayReport','','data-page="'+(page+1)+'"','primary'):''}</div>`,`${page+1} / ${pages} · 费用已计入本周结算`);}
